-- MATCHAの記事を matcha_articles へ入れる（lang=ja）。
-- scripts/import-matcha-articles.mjs --dry-run --sql --by-prefecture --per-prefecture 3 --lang jp
-- 取得日 2026-08-11。県ごとの一覧（list?region=100+県コード）から集め、
-- どの県かは記事のパンくずで決めている。47都道府県すべてに記事がある。
-- 同じ url+lang は入れ直す（upsert）ので、何度貼っても増えない。
-- 5言語ぶんある。1ファイルずつ SQL Editor に貼る。

insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at)
values
  ('https://matcha-jp.com/jp/27358', 'ja', 13, '東京旅行で絶対外せない！GINZA SIXならではの「限定手土産」と「美食体験」完全ガイド', '世界のラグジュアリーブランドや現代アート、美食が集結する「GINZA SIX」は、銀座を代表するランドマークです。本記事では、上質な手土産や名店グルメ、優雅なアフタヌーンティーまで、GINZA SIXならではの魅力を通して、洗練された銀座のひとときをご紹介します。

建物はB6Fから地上13Fまでの複合商業施設で、うち商業施設の9つのフロアには約240店舗が軒を連ねています。また、B3Fには、日本の伝統芸能「能」を鑑賞できる「観世能楽堂(かんぜのうがくどう)」を併設。ショッピングだけでなく、日本文化にも触れられます。

なかでも見逃せないのが、施設のシンボルでもある中央吹き抜け空間に展示されている、国際的アーティスト、ジュリアン・オピー(Julian Opie)による大規模なインスタレーション作品。エスカレーターに乗る際は、ぜひ見上げて鑑賞してみてください。

ひとつは、ミシュラン星獲得店が手がける和菓子ブランド「赤坂おぎ乃和甘(わかん)」。もうひとつは、日本の名山をモチーフにした美しい和洋菓子で注目を集める「小楽園KIOSK」です。', '["https://resources.matcha-jp.com/resize/720x2000/2026/07/02-266419.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/02-266420.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/02-266421.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/02-266422.webp"]'::jsonb, '2026-07-02'::timestamptz),
  ('https://matcha-jp.com/jp/1361', 'ja', 1, '一度は行きたい! 新千歳空港にある「北海道ラーメン道場」', '北海道の新千歳空港の中にある「北海道ラーメン道場」を紹介している記事です。北海道には醤油（正油）ラーメン、味噌ラーメン、塩ラーメンなどがありますが、それぞれの特徴も紹介しています。

北海道に飛行機で行く場合、新千歳空港を使うと札幌などの都心部に近くて便利です。そして、札幌に行けば美味しいラーメン店や、北海道ならではの美味しい店などがたくさんあります。

でも実は、札幌まで行かなくても新千歳空港の中に「北海道ラーメン道場」という、北海道の人気ラーメン店が集まっている一画があります。「北海道ラーメン道場」では、醤油ラーメン、味噌ラーメン、塩ラーメン、そしてちょっと変わったラーメンまで、本当に美味しいラーメンが食べられます。

「北海道ラーメン道場」は新千歳空港の国内線ターミナルビル3Fにあります。入り口は幾つかありますが、こちらの入り口には「北海道ラーメン道場」のシンボル的な存在の、ラーメンの器でできた北海道の地図があります。', '["https://resources.matcha-jp.com/resize/720x2000/2022/10/13-130768.jpeg","https://resources.matcha-jp.com/resize/720x2000/2022/10/13-130769.jpeg","https://resources.matcha-jp.com/resize/720x2000/2022/10/13-130770.jpeg"]'::jsonb, '2015-11-09'::timestamptz),
  ('https://matcha-jp.com/jp/1636', 'ja', 1, '東京から北海道までの行き方を時間や料金で徹底比較！', 'おいしいグルメに美しい自然、雪と、魅力がもりだくさんの北海道。本記事では、東京から北海道に行く際の交通手段として、飛行機、鉄道(新幹線)、レンタカーの料金・時間を比較してみました。併せて、北海道内の移動手段に関しても紹介しています。

北海道は日本の47都道府県のうち、最大の面積を誇ります。北海道内における都市間の距離は遠いので、「東京から北海道」と言ってもどの地域に行きたいかによって、どの交通手段が最適か見極めなければなりません。

今回は、2022年12月現在における情報に基づき、料金、時間、便利さを比べてみました。

北海道には空港が11カ所あり、その内9空港に羽田空港からの直行便が飛んでいます。', '["https://resources.matcha-jp.com/resize/720x2000/2022/02/16-122822.webp","https://resources.matcha-jp.com/archive_files/jp/2016/01/tokyo_to_nagoya_20160125c.webp","https://resources.matcha-jp.com/resize/720x2000/2022/10/13-130768.jpeg","https://resources.matcha-jp.com/archive_files/jp/2016/01/tokyo_to_nagoya_20160125b-700x525.webp"]'::jsonb, '2018-09-14'::timestamptz),
  ('https://matcha-jp.com/jp/3970', 'ja', 2, '【2026年】青森ねぶた祭へ行こう！日程・アクセス・見どころ', '2026年の青森ねぶた祭は8月2日～7日に開催。前夜祭や運行時間、有料観覧席、会場へのアクセス、跳人として参加する方法を詳しく紹介します。

青森ねぶた祭とは、日本の東北地方にある青森県の伝統的な祭りです。冒頭の写真のような巨大な燈籠「ねぶた」が、青森市内の大通りを進む豪壮なイベントです。

青森ねぶた祭は、七夕（※1）の夜に川や海へ灯籠を流して無病息災を祈る灯籠流しが起源のひとつといわれています。この行事が東北地方で「ねぶり流し」と呼ばれていたことから、次第に「ねぶた」と呼ばれるようになったという説があります。

1716年ごろの江戸時代中期には、灯籠を持った人々が踊る祭りへと変化し、山車も登場。江戸時代後期になると、歌舞伎などを題材にした大型の灯籠が登場し、現在の青森ねぶた祭につながっていきました。', '["https://resources.matcha-jp.com/resize/720x2000/2017/04/03-23160.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/03-23157.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/03-23158.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/03-23159.webp"]'::jsonb, '2017-02-01'::timestamptz),
  ('https://matcha-jp.com/jp/7118', 'ja', 2, '東北の歴史、伝説、文学を知る！冬に巡る仙台、岩手、青森の旅', '東北地方は冬になると深い雪に覆われ、かつては不便な土地と見られていました。しかし独特な文化や、歴史的に有名な人物が多く誕生した土地でもあります。戦国大名・伊達政宗、作家・太宰治、宮沢賢治、そして有名な伝説の生き物「河童」など、東北発祥の文化を巡ってみましょう！

日本列島の北部にある東北地方は、その地域ならではの歴史と文化、伝説が存在しています。

特に冬は、東北地方が白銀の世界に変わる季節。東北らしさを体験しに、宮城県仙台市、岩手県遠野市、青森県津軽半島へ「文化の旅」に出かけましょう！

東北地方の歴史上の人物といえば、"独眼竜(※1)の戦国大名"とも呼ばれる伊達政宗ではないでしょうか。東北最大の都市・仙台市では、彼が築いた歴史の跡が残されています。', '["https://resources.matcha-jp.com/resize/720x2000/2019/03/04-72429.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/06-72558.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/04-72392.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/04-72356.webp"]'::jsonb, '2019-03-04'::timestamptz),
  ('https://matcha-jp.com/jp/1666', 'ja', 2, '有形文化財を活用したレトロな佇まい「スターバックス コーヒー 弘前公園前店」', '青森県弘前市に、日本で2番目に有形文化財を利用したスターバックスの店舗があります。大正時代のレトロな雰囲気が漂う「スターバックスコーヒー弘前公園前店」は、東北地方にあります。

本州の最北端、東北地方に属する「青森県」。冬には何メートルもの雪が降り積もるこの場所に、ひときわ趣のあるカフェが存在するのをご存知でしょうか。

スターバックス コーヒー 弘前公園前店は、神戸北野異人館店に続いて日本で2番目にオープンした、有形文化財を利用したスターバックスの店舗です。大正時代を思わせるレトロな出で立ちはもちろんのこと、そのほかさまざまな魅力が利用者を楽しませてくれます。その一部をご紹介します。

弘前公園前店のある青森県弘前(ひろさき)市は、桜の名所として有名な場所。春には弘前城とその周囲に咲き乱れる桜を見に、世界中から見物客が訪れます。また真冬には、何メートルもの雪が積もる、日本でも有数の寒い地域でもあります。', '["https://resources.matcha-jp.com/resize/720x2000/2024/12/03-213266.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/03-213267.webp","https://resources.matcha-jp.com/archive_files/jp/2016/02/Starbucks-coffee_Hirosaki_20160206_1.webp","https://resources.matcha-jp.com/archive_files/jp/2016/02/Starbucks-coffee_Hirosaki_20160206_9.webp"]'::jsonb, '2018-12-21'::timestamptz),
  ('https://matcha-jp.com/jp/6983', 'ja', 3, '幻の和牛「短角牛」とは？オススメ料理と産地・岩手県のレストランを紹介', '訪日旅行客にも大人気の和牛。実は北日本には、"幻の和牛"と呼ばれる貴重な牛がいるのです。その名も「短角牛」といい、一般的な霜降り肉とは異なった、赤身の肉質が最大の特徴。ヘルシーで高タンパク、鉄分などのミネラルも豊富で、健康的でとてもおいしい牛肉です。今回は主要な生産地の1つである岩手県で、短角牛を扱う飲食店を紹介します。

和牛と聞いてイメージされる霜降りの牛肉と異なり、脂身の少ない赤身肉が特徴。肉の旨味が強く、更に低カロリーかつ高タンパクで、身体にいい肉なのです。

短角牛の肉は、適した調理方法もほかの和牛とは異なります。代表的な黒毛和牛は、霜降り肉を薄切りにして、すき焼きやしゃぶしゃぶにするのが好まれます。一方、赤身肉である短角牛の場合、肉質の特長を生かしたステーキ、焼肉やハンバーグなどで召し上がっていただくと牛肉のおいしさが堪能できます。

生産地は北日本に集中しており、主に北海道・青森県・岩手県・秋田県で育てられています。', '["https://resources.matcha-jp.com/resize/720x2000/2019/01/17-69530.webp","https://resources.matcha-jp.com/resize/720x2000/2019/02/04-70510.webp","https://resources.matcha-jp.com/resize/720x2000/2019/01/17-69531.webp","https://resources.matcha-jp.com/resize/720x2000/2019/01/17-69532.webp"]'::jsonb, '2019-01-17'::timestamptz),
  ('https://matcha-jp.com/jp/23226', 'ja', 3, '岩手・宮古のB級・名物グルメ4選！瓶ドンやラーメンの名店を紹介！', '岩手県の宮古に行ったらぜひ味わいたいグルメと、地元の名物料理を味わえるおすすめの店舗を紹介した記事です。岩手県の三陸海岸に面する宮古市は、新鮮な海の幸が豊富です。瓶ドンや海鮮丼、寿司、ラーメンなど、おすすめのグルメをぜひチェックしてみましょう。

本州最東端の岩手県宮古市には、三陸鉄道や浄土ヶ浜などの観光スポットがあります。宮古に観光に来たら、地元の名物グルメを味わうのもおすすめです。宮古には瓶ドンやラーメン、海鮮丼、寿司など名物料理やB級グルメがあります。

この記事では、宮古の絶品グルメと、名物料理を味わえるおすすめの店舗を紹介します。

▼宮古観光で外せない！名物料理＆絶品B級グルメ ▼宮古のグルメは「海の幸」と「山の幸」 ▼1位. 瓶ドン', '["https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215050.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215051.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215052.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215053.webp"]'::jsonb, '2024-12-13'::timestamptz),
  ('https://matcha-jp.com/jp/24209', 'ja', 3, '盛岡を半日で巡る観光モデルコース！日帰りでスポットを全力で楽しもう', '盛岡の観光モデルコースを半日で巡るプランを紹介！盛岡城跡公園で歴史を感じ、初駒 本店で名物わんこそばを堪能し、盛岡八幡宮で参拝するルートで、歴史とグルメを楽しめます。短時間でも盛岡の魅力を満喫できるコースです。

盛岡は歴史や文化、美しい自然が融合する魅力的な街です。市内には南部藩の歴史を感じられる史跡や、日本三大麺の一つ「わんこそば」をはじめとする絶品グルメが楽しめる飲食店が多数あります。

また、春の桜や秋の紅葉の名所としても知られています。特に、盛岡城跡公園の石垣や風情ある街並み、盛岡八幡宮の荘厳な社殿は必見です。

半日でも充実した観光を楽しめるエリアが揃っており、歴史とグルメを堪能したい方に最適な旅先です。', '["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225284.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225288.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225286.webp"]'::jsonb, '2025-02-20'::timestamptz),
  ('https://matcha-jp.com/jp/6880', 'ja', 4, '松島「雪竹屋」で見つかる"世界でここだけ"の日本みやげ', '東北地方にある日本三景「松島」は、観光スポットの多い人気の観光地です。今回紹介するおみやげ店「雪竹屋」は、日本文化が伝わるような、東北地方のおみやげが買える店。手作りの「ここでしか買えないもの」をメインに置いています。店内で作っているせんべいも名物の1つ。本記事では雪竹屋で買うべきおみやげを紹介します。

東北地方、仙台駅から電車で約30分の場所に、人気の観光地「松島」があります。人気の理由はその景色。松島湾に点々と浮かぶ島と松の景色がとても綺麗な場所です。厳島神社のある広島県宮島、京都府の天橋立と並び、日本の中でもとくに景色が美しい「日本三景」とも呼ばれています。

ほか、国宝である瑞巌寺(ずいがんじ)、朱塗りが綺麗な福浦橋(ふくうらばし)など観光スポットも多数。おみやげにぴったりのグルメや雑貨もあり、1度来れば何度も訪れたくなる場所です。

今回は、松島でしか買えない、日本の文化に焦点をあてたおみやげ店「雪竹屋(ゆきたけや)」を紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2018/12/06-67592.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/06-67593.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/04-67331.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/06-67594.webp"]'::jsonb, '2018-12-06'::timestamptz),
  ('https://matcha-jp.com/jp/6750', 'ja', 4, '田代島の観光ガイド『ネコ好きの楽園』へのアクセスやネコスポットも丸わかり', '東北地方、宮城県石巻市の太平洋に浮かぶネコの島「田代島」。ここには数百匹のネコが、島の人と仲良く暮らしています。ネコと一緒に戯れる瞬間は幸せそのもの。本記事では、田代島の魅力やアクセス情報、フェリー料金、おすすめルートを紹介。ネコ島でくつろぐネコ達に、たっぷり癒されてください！

田代島(たしろじま)は、東北地方・宮城県東部の石巻市にある小さな島。周囲約11キロメートルの島には、130匹以上のネコが、島の人と一緒に暮らしています。住民よりもネコの数が多く、「猫の島」とも呼ばれ、ネコ好きたちの注目を集めています。

田代島までは、石巻駅からバスとフェリーを使って行くのが一般的。石巻駅は仙台から電車で約1時間です。アクセス方法については記事の後半で詳しく紹介します。

田代島の港は、島の北部にある「大泊港(おおどまりこう)」と南部「仁斗田港(にとだこう)」の2種類。', '["https://resources.matcha-jp.com/resize/720x2000/2018/10/29-65432.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/02-65659.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/29-65431.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/29-65433.webp"]'::jsonb, '2018-11-08'::timestamptz),
  ('https://matcha-jp.com/jp/6729', 'ja', 4, '東北・宮城県の霊島「金華山黄金山神社」へ。神秘的なパワーをもらう1泊2日の旅', '東北地方・宮城県にある金華山黄金山神社は、金運にご利益のあるパワースポット。「3年連続でお参りに行くと、一生お金に困らない」とも言われています。民家のない島には、人よりも"神の使い"のシカが多く生息し、とても静かで神秘的な雰囲気。1泊して普段とは違った体験をしてみませんか。

「3年連続でお参りに行くと、一生お金に困らない」と言い伝えられる金運スポット、金華山黄金山(きんかさんこがねやま)神社(以下、黄金山神社)。宮城県で、日本で初めて金が産出されたことを祝し、建てられた神社です。

黄金山神社は、平安時代の終わり頃から権力者の寄付が行われ、大切にされてきた場所です。島全体は神様が宿る聖域として、修験者も多く訪れ、神聖な場所としても崇められてきました。また、江ノ島神社、厳島神社に並ぶ「日本五大辯財天」(※1)としても有名。

ここの参拝方法は、神社と同じ敷地内の宿坊で、1泊するスタイルが主流だったそう。今は日帰り参拝も多いですが、神社ならではの儀式を体験したり、人混みから離れ静かな時を過ごしたい方には、宿泊参拝がオススメです。', '["https://resources.matcha-jp.com/resize/720x2000/2018/10/24-65155.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/24-65156.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/24-65201.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/24-65157.webp"]'::jsonb, '2018-11-12'::timestamptz),
  ('https://matcha-jp.com/jp/4198', 'ja', 5, '【2026】秋田「竿燈まつり」の日程・場所などをまとめて紹介！1万個の提灯に感動', '2026年の秋田竿燈まつりは8月3日～6日に開催。夜本番やドローンショー、昼竿燈、観覧席の料金、アクセス、見どころを紹介します。

「秋田竿燈まつり」とは、東北地方の秋田県秋田市で毎年8月3日～6日に開催される伝統的な祭りです。

五穀豊穣や無病息災を祈る祭りで、青森の青森ねぶた祭、宮城の仙台七夕まつりとともに「東北三大祭り」のひとつに数えられています。

秋田竿燈まつりは、旧暦（※1）の七夕やお盆に行われていた「眠り流し」が起源といわれています。', '["https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21813.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21814.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21810.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21809.webp"]'::jsonb, '2017-04-06'::timestamptz),
  ('https://matcha-jp.com/jp/3183', 'ja', 5, '【2026年最新】東北地方の紅葉見頃とおすすめ名所10選', '仙台の定禅寺通や松島の円通院、平泉、奥入瀬渓流、十和田湖など、東北地方を代表する紅葉の名所10か所を紹介します。各スポットの見頃時期や周辺の楽しみ方も合わせて解説しています。

参考 : お天気ナビゲータ／ウェザーニュース（各サイトの2026年シーズンの紅葉見頃予想は、例年9月頃から順次公開されます）

東北地方は、日本の北部にある6県(青森県、岩手県、宮城県、秋田県、山形県、福島県)を総称した地域名。世界遺産の青森県「白神山地」、岩手県「平泉」など雄大な自然や歴史的建造物も残り、美しい景色が広がる場所です。

紅葉の時期は場所にもよりますが、例年10月中旬～11月下旬。東京よりも半月ほど早く見ごろを迎えます。', '["https://resources.matcha-jp.com/resize/720x2000/2025/10/07-246201.webp","https://resources.matcha-jp.com/resize/720x2000/2023/09/15-145999.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/01-82825.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/01-82751.webp"]'::jsonb, '2016-10-28'::timestamptz),
  ('https://matcha-jp.com/jp/2013', 'ja', 5, '【2026】日本のユニークな花火大会5選！昼花火や伝統の仕掛け花火も紹介', '日本全国にある一風変わっためずらしい花火大会5選を最新情報で解説します。水上スターマインや昼花火、伝統の手筒花火など、ユニークな見どころを紹介します。

日本の夏の風物詩「花火」。中でも、日本全国にはめずらしい花火大会があるのをご存知ですか？

ひとくちに「花火」と言っても、その見た目・インパクトもさまざま。流星のように夜空に流れる花火や、激しく燃え上がる花火など、今回は日本各地にあるユニークな花火大会をご紹介します！

長野県諏訪市の諏訪湖の上で行われる花火大会。全国から集結した花火職人による斬新なアイディアから生まれた花火が、メッセージや音楽と共鳴しながら打ち上げられます。また諏訪湖ならではの演出である、湖面を鮮やかに染める精緻な水上スターマインも大注目です。', '["https://resources.matcha-jp.com/resize/720x2000/2024/07/16-188066.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/16-188069.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/16-188071.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/16-188072.webp"]'::jsonb, '2016-06-30'::timestamptz),
  ('https://matcha-jp.com/jp/6548', 'ja', 6, '映画『3月のライオン』の舞台、山形県の山寺とフルーツパフェを楽しむ旅', '山形県を訪れるなら、見逃せないのが山寺です。将棋をテーマとした映画『3月のライオン』の撮影地にもなりました。さらに山形県は、さくらんぼやももなどフルーツの生産地でも有名です。今回は乗り放題の「JR EAST PASS(東北エリア)」を使用し、山寺と季節のフルーツを楽しむ旅に出かけましょう！

山形県には自然の美しい景観やご当地グルメのほか、歴史的にも有名な観光スポット山寺や、くだもの狩りができる観光農園があります。

今回のスタート地点は、山形県天童市。東京駅から天童駅までは、新幹線で約2時間半〜3時間です。今回はJR東日本の乗り放題きっぷ「JR EAST PASS(東北エリア)」を使用して、山寺の歴史スポットと絶品スイーツを満喫するコースを紹介します！

古くから日本で親しまれている「将棋」は、2人が将棋の盤の上で、交互に駒を動かして勝敗を競う対戦ゲームです。天童市は将棋の駒作りで有名な場所。街には各所に駒をモチーフとしたモニュメントを見つけることができます。', '["https://resources.matcha-jp.com/resize/720x2000/2018/09/20-63079.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/20-63080.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/20-63081.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/20-63082.webp"]'::jsonb, '2018-10-30'::timestamptz),
  ('https://matcha-jp.com/jp/25908', 'ja', 6, '【福島・宮城・山形】東北の冬を歩く～樹氷・温泉・歴史探訪～', '冬になると東北（南東北を含む）は、雪と氷に覆われた別世界へと変貌を遂げます。凛とした空気、白銀の樹氷、雪化粧した古街、あたたかな湯けむり……。雪国ならではの風景と情緒を求めて、福島・宮城・山形を巡る旅は、心を震わせる体験になるでしょう。

冬になると東北の大地は一面の銀世界に包まれます。澄んだ空気、きらめく雪、そして心を温めてくれる温泉や郷土料理。そんな日本の原風景ともいえる冬の魅力を味わうことができるのが、福島・宮城・山形の南東北エリアです。ローカル線に揺られて雪景色を眺めたり、昔ながらの宿場町を歩いたり、幻想的な樹氷に出会ったり──そこには、都会の喧騒を忘れさせてくれる特別な時間が広がっています。

今回ご紹介するのは、福島の只見線や大内宿・会津若松城、宮城のキツネ村やすみかわスノーパークの樹氷ツアー、そして山形の蔵王樹氷や銀山温泉。雪国ならではの絶景とぬくもりをめぐる旅へ、さあ出発してみませんか。

福島と新潟を結ぶ只見線は、雪に覆われた冬の季節になると、まるで絵本の世界に迷い込んだかのような光景が広がります。特に有名なのは、只見川第一橋梁を渡る列車の姿です。雪で白く染まった渓谷を列車が静かに進む様子は、時間がゆっくりと流れるような感覚を旅人に与えます。', '["https://resources.matcha-jp.com/resize/720x2000/2025/09/29-245363.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/29-245364.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/29-245365.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/29-245366.webp"]'::jsonb, '2025-09-29'::timestamptz),
  ('https://matcha-jp.com/jp/25347', 'ja', 6, '【山形県米沢市】グルメ・自然・体験がぎゅっと詰まった米沢の魅力を満喫する1泊2日', '名古屋から約2時間で行ける人気の観光スポット岐阜県郡上市。城下町での食べ歩き、歴史を感じる町歩き、そして郡上おどりと清流長良川の美しい水に癒されながら、風情のある町を楽しむことができます。今回はそんな郡上にあるおすすめの観光スポットを紹介します

山形県米沢市は、四季折々の風景が美しい城下町として有名な場所です。戦国武将の上杉謙信や上杉鷹山にゆかりがある歴史の町でありながら、絶品グルメの「米沢牛」や、季節になると蛍が舞う「小野川温泉」、自然を満喫できる「天元台高原」など、各所に見どころが満載です。 東京からは山形新幹線を使って約2時間で行くことができる山形県米沢市。今回は米沢市を最大限楽しむための1泊2日で回るべきおすすめスポットを紹介します。まだ知らない山形県米沢市の魅力をこの記事を通して少しでも感じてもらえると嬉しいです。この記事では特に「グルメ」「絶景」「温泉」を軸に紹介していきます。

駅近くにはレンタカーはもちろん、観光バス、タクシーと選択肢があって、車に乗れなくても観光を楽しむことはできそうです。特に春や秋は自転車を借りての観光も気持ちよさそうです。

米沢市の観光では、気候によってはレンタサイクルの利用もおすすめです。市内には3か所、米沢駅、上杉伯爵邸（和庭）、道の駅米沢でレンタサイクルを借りることができます。米沢駅と上杉伯爵邸（和庭）間であれば「乗り捨て返却」も可能なので、自分の旅行スタイルに合わせた利用が可能なのは嬉しいですね。また、レンタサイクルは電動自転車となっているため、楽に移動できます。台数は限られますが、チャイルドシート付のものもあるので、小さな子供連れでも利用が検討できます。', '["https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238260.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238282.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238278.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238279.webp"]'::jsonb, '2024-12-27'::timestamptz),
  ('https://matcha-jp.com/jp/24267', 'ja', 7, '福島市の気温は？年間平均と月ごとの気温、ベストな服装を紹介', '福島市の気温は季節ごとに大きく変化します。本記事では、過去のデータをもとに1月から12月までの月ごとの気温と、それぞれの時期に適した服装をまとめています。旅行や外出の際の参考にぜひご活用ください。年間の気候を把握して快適に過ごしましょう。

福島県は、「会津地方」「中通り」「浜通り」の3つに分かれており、福島市が属する中通り地方は、盆地特有の気候が特徴です。

日本海側と太平洋側の気候の中間にあたる福島市は、夏は湿度が高く蒸し暑くなり、冬は冷たい風が吹き、雪も降る寒冷な環境になります。

2024年のデータによると、最も寒い日は-4.4℃、最も暑い日は36.6℃を記録しており、年間平均気温は15.3℃です。', '["https://resources.matcha-jp.com/resize/720x2000/2025/02/26-225917.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/26-225918.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/26-225919.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/26-225920.webp"]'::jsonb, '2025-02-26'::timestamptz),
  ('https://matcha-jp.com/jp/24299', 'ja', 7, '【2025】福島・鶴ヶ城公園の桜の見頃は？ライトアップやイベント情報まとめ', '福島県の会津若松にある鶴ヶ城公園は「日本さくら名所100選」に選ばれた花見の名所。例年4月上旬から5月上旬に約1000本の桜が咲き誇ります。夜桜ライトアップや「鶴ヶ城さくらまつり」といったイベントなどの情報をお伝えします。

会津若松市の象徴、鶴ヶ城（若松城）は、春になると約1000本もの桜が城を取り囲み、壮観な景色を生み出します。

その美しさから鶴ヶ城公園は「日本さくら名所100選」にも選ばれており、会津を代表する桜の名所となっています。

本記事では、2025年最新の情報に基づき、鶴ヶ城公園の桜の見頃やイベントや楽しみ方をご紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226232.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226234.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226233.webp","https://resources.matcha-jp.com/resize/720x2000/2025/12/26-254095.webp"]'::jsonb, '2025-02-27'::timestamptz),
  ('https://matcha-jp.com/jp/24217', 'ja', 7, '日本三大桜のひとつ・三春滝桜の見どころや開花時期は？福島の花見名所に行こう', '三春滝桜は、福島県を代表する桜の名所です。日本三大桜のひとつであり、推定樹齢1000年以上のベニシダレザクラを鑑賞できます。歴史も感じられるので、ぜひ訪れてみてください。

日本三大桜のひとつとして名高い三春滝桜は、推定樹齢1000年以上のベニシダレザクラが咲き誇る絶景スポットです。

2025年も、例年通り4月中旬に見頃を迎えるこの桜は、圧倒的な開花の美しさで訪れる人々を魅了します。福島県内で桜の名所を探している方は、ぜひこの歴史ある桜の魅力に触れてみてください。

三春滝桜は、日本三大桜のひとつとして名高く、福島県にその存在を刻む歴史ある桜です。推定樹齢は1000年以上とされ、ベニシダレザクラ（エドヒガン系）の代表例として、古くからその美しさと威厳を誇示しています。', '["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225359.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225360.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225361.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225362.webp"]'::jsonb, '2025-02-20'::timestamptz),
  ('https://matcha-jp.com/jp/5256', 'ja', 8, 'ロープウェイで山頂へ！東京から日帰りで行ける「筑波山」で関東平野を一望', '富士山と並ぶ名峰でありながら、登山装備を持っていなくても楽しめる筑波山。自然や郊外の景色を楽しんでみたい方、東京にはない自然の写真を撮ってみたい方、神社仏閣に興味のある方におススメです。

筑波山は、2つの山頂を持つ、茨城県の山。日本一高い山「富士山」と並び、昔から「西の富士、東の筑波」と言われ親しまれてきました。

筑波山は標高約877メートル。山の中はケーブルカーやロープウェイ、登山道が整備されているので、登山グッズを持っていなくても楽しめます。

また、山の中腹には縁結びで有名な「筑波山神社」もあり、自然や神社仏閣に興味のある方にオススメのスポット。', '["https://resources.matcha-jp.com/resize/720x2000/2017/10/25-39634.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/25-39635.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/25-39619.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/25-39617.webp"]'::jsonb, '2019-03-25'::timestamptz),
  ('https://matcha-jp.com/jp/4078', 'ja', 8, '夢を叶える強力なパワーをもらえる！茨城県稲敷市の大杉神社', '茨城県にある大杉神社は、具体的で明確な「夢」を叶える手助けをしてくれる日本で唯一の神社です。悪縁を断ち切ってくれる「かわらけ割り」もあるので、夢を叶えたい方はもちろん良い縁を呼び込みたい人にオススメです。

大杉神社は、関東地方の茨城県稲敷市にある神社です。ここは、日本唯一の「夢むすび大明神」、つまり「夢を叶えてくれる神社」と呼ばれています。

健康祈願や交通安全などのお願いをする一般的な神社と違って、この神社には具体的で明確な夢や目標を叶えてくれる神様がいるのだそう。

拝殿(※1)や楼門(※2)は、朱色を中心とした鮮やかな色彩が特徴。境内は様々な色の建物や彫刻で囲まれており、市街地にある神社とは思えない特別な雰囲気を感じることができます。', '["https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21815.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21816.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21817.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/21-21818.webp"]'::jsonb, '2017-10-02'::timestamptz),
  ('https://matcha-jp.com/jp/10854', 'ja', 8, '国営ひたち海浜公園の近く！絶品の干物と地魚が楽しめる那珂湊', '人気観光地・国営ひたち海浜公園の近くにある那珂湊。東京からアクセスのよいこの港町では、干物やみりん干しなど、おいしい水産加工品がたくさんあります。本記事では、干物が人気の水産加工ブランド「五代目常造」と、地魚が集まる「那珂湊おさかな市場」を紹介します。

広大な丘に一面に咲く青いネモフィラの花。日本旅行に関心のある方は、こんな写真を見たことがあるのではないでしょうか？

米国CNNの「日本の最も美しい場所36選」のひとつに選ばれた「国営ひたち海浜公園」は、東京から約2時間30分と、アクセスしやすい場所にあります。

この「国営ひたち海浜公園」の近くのある那珂湊(なかみなと)は、明治時代から漁業で栄えてきた港町。今も、ヒラメやシラス、カレイ、アワビなど、さまざまな魚介類が水揚げされています。', '["https://resources.matcha-jp.com/resize/720x2000/2022/01/05-119602.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/05-119611.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/05-119612.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/05-119613.webp"]'::jsonb, '2021-09-17'::timestamptz),
  ('https://matcha-jp.com/jp/5443', 'ja', 9, '「日光金谷ホテル」——著名人も感動した、歴史と文化を感じる宿', '栃木県の日光にある「日光金谷ホテル」は、訪日観光客を140年にわたっておもてなししてきました。時代を超えて受け継がれる老舗ホテルの魅力は何なのか？ ヘレン・ケラー、アルベルト・アインシュタインも宿泊した日光金谷ホテルを紹介します！

ヘレン・ケラー、アルベルト・アインシュタイン、アメリカの元大統領ドワイト・アイゼンハワー。この歴史上の人物には、ある共通点があります。それは、来日時の宿泊先に「日光金谷ホテル」を選んだことです。

日光金谷ホテルは、日本で初めて訪日観光客のために造られたホテル。日光の有名な観光スポット「神橋」や、世界遺産「日光東照宮」の近くにあります。

日光金谷ホテルの物語は、明治3(1870)年にアメリカ宣教師兼医者、そして日本のヘボン式ローマ字綴りを考案した「J.C.ヘップベーン」(ヘボン博士)が来日したことから始まります。', '["https://resources.matcha-jp.com/resize/720x2000/2017/12/01-42841.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/30-42726.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/01-42842.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/01-42818.webp"]'::jsonb, '2017-12-01'::timestamptz),
  ('https://matcha-jp.com/jp/9264', 'ja', 9, 'ここは200年前!?那須高原の帰りは江戸時代風「羽生PA」と家族連れも嬉しい「蓮田SA」へ', '東京から車で2時間半ほどの高原リゾート・那須高原から、東京方面への帰り道は、限定グルメが楽しめる高速道路の休憩スポットに立ち寄りましょう！ 江戸時代の街並みが再現された羽生PA(上り)や、設備の充実した蓮田SA(上り)など、施設ごとに魅力的な特色もあります。好みに応じて休憩場所を選んでみてください。

浅草、新宿、原宿など、観光客で賑わう東京を観光したら、翌日は自然や動物に囲まれて過ごしてみませんか。オススメは、東京から日帰りで行ける那須高原。車で2時間半ほどの場所にある高原リゾートです。

チューリップやマリーゴールド、コスモスなど1年を通して彩り豊かな花が咲き変わる「那須フラワーワールド」、ハリネズミやヒツジなどの可愛い動物が魅力の「那須高原 南ヶ丘牧場」、約300頭のアルパカが放牧されている「那須アルパカ牧場」を巡れば、旅の疲れも癒されること間違いなし。

また、夏は避暑地、秋は紅葉の綺麗な観光地としても人気の場所。温泉街もあるので、泊りで訪れても充実した旅になるでしょう。', '["https://resources.matcha-jp.com/resize/720x2000/2020/01/15-95049.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/16-95095.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/15-95006.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/17-95191.webp"]'::jsonb, '2020-01-15'::timestamptz),
  ('https://matcha-jp.com/jp/2625', 'ja', 9, 'バスと電車どっちが安い？東京から日光への行き方', '日光は栃木県の北西部に位置する市で、美しい自然と、世界文化遺産に登録された東照宮を含む神社仏閣や、自然にも恵まれた観光地です。日帰りも可能な東京から日光への行き方を、バスや電車に分けて紹介します。

日光市は、栃木県の北西部に位置する市です。華厳の滝(けごんのたき)や、中禅寺湖(ちゅうぜんじこ)などの美しい自然と、世界文化遺産に登録された東照宮を含む神社仏閣、温泉もある自然豊かな観光地です。特に見事な紅葉を楽しめる秋にオススメの場所です。

栃木県は関東地方の一県。東京から電車やバス、車で行ける距離なので、日帰りで観光する人もたくさんいます。

電車で行く方法はいくつかありますが、ここでは、出発地東京都内、終着地を東武日光駅としての行き方を紹介いたします。', '["https://resources.matcha-jp.com/resize/720x2000/2020/02/26-98221.webp","https://resources.matcha-jp.com/resize/720x2000/2020/02/26-98222.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/01-122018.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1700.webp"]'::jsonb, '2019-04-12'::timestamptz),
  ('https://matcha-jp.com/jp/9330', 'ja', 10, '世界遺産のある街・富岡でやりたい5つのこと〜路地裏歩き、グルメ、機織り体験', '世界遺産「富岡製糸場」のある街・群馬県富岡市。でも、その魅力は世界遺産だけにとどまりません。製糸場周辺はレトロな建物や古民家カフェなどが立ち並び、路地裏散歩にうってつけ。好奇心を携えて、富岡の街へ迷い込みましょう！

群馬県の富岡と聞けば、世界遺産に登録された「富岡製糸場」をイメージする人が多いでしょう。しかし、製糸場を訪れても、その周りをじっくり歩いてみた方はあまり多くないかもしれません。

でもそれでは、もったいない！ 実は、製糸場周辺には古い建物、レトロカフェ、趣深い路地がそこかしこにあり、世界遺産を中心としながら、今も地元の人々の暮らしが息づいているのです。富岡はリゾート地・軽井沢からもアクセスしやすく、セットで訪れるのもオススメ。新しい富岡を探す旅に、出発しましょう！

富岡を訪れるなら、やはりまずはここ。2014年に世界遺産に登録された「富岡製糸場」です。広大な敷地内に、日本近代製糸業の礎を築いた建造物群が、1872年の創業時の様子をよく留めつつ、保存されています。', '["https://resources.matcha-jp.com/resize/720x2000/2020/01/29-95945.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/29-95946.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/28-95864.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/28-95871.webp"]'::jsonb, '2020-01-26'::timestamptz),
  ('https://matcha-jp.com/jp/3989', 'ja', 10, '金銀2種類の湯が楽しめる群馬の名湯・伊香保温泉～日帰り入浴施設、旅館、アクセス情報など～', '群馬県渋川市伊香保町にある温泉で、草津温泉とともに群馬を代表する名湯です。温泉街には古い建物や歴史ある神社仏閣が残り、足湯や飲泉所もあるので、日本の古きよき温泉街の雰囲気を楽しめます。伊香保温泉へのアクセス、伊香保温泉の効能や楽しみ方と、オススメの日帰り温泉、旅館をご紹介します。

伊香保温泉といえば、石段の温泉街が有名で、365段もの石段が温泉街の中心にあります。両脇には旅館やみやげ店が並び、50年前の日本にタイムスリップしたかのようなノスタルジックな雰囲気を味わえます。

石段の途中には足湯や温泉の水が飲める飲泉所、お茶屋さんなどもありますので、足を休めたり喉の乾きを潤したりしながら、散策を楽しむとよいでしょう。

伊香保温泉には、黄金(こがね)の湯と白銀(しろがね)の湯の2種類のお湯があります。', '["https://resources.matcha-jp.com/resize/720x2000/2017/02/08-18080.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17906.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17907.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17908.webp"]'::jsonb, '2017-02-14'::timestamptz),
  ('https://matcha-jp.com/jp/19178', 'ja', 8, '【2026年版】GWは穴場へ！電車で行ける関東のおすすめ観光地10選', '2026年のゴールデンウィークを混雑回避で楽しもう！千葉の佐原や群馬の芝桜公園など、公共交通機関でもアクセスしやすい関東近郊の穴場スポット10選を紹介します。日帰り旅行や週末のおでかけ計画にぜひお役立てください。

ゴールデンウィークはまとまったお休みが取れることから、少し遠くに出かけたり普段できない体験をしたりして楽しみたいですよね。しかし定番の観光地は渋滞や混雑に巻き込まれやすいため、できれば穴場スポットを狙いたいもの。

この記事では、1泊や日帰りでも出かけられる関東近郊のスポットを紹介。電車など公共交通機関でも行きやすい穴場を厳選しました。

ローカル観光やグルメを愛する神奈川県在住・一児の母である筆者から、オススメのポイントや混雑を避ける方法などもご紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2024/03/26-175204.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/26-175203.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/26-175200.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/26-175199.webp"]'::jsonb, '2024-03-25'::timestamptz),
  ('https://matcha-jp.com/jp/3235', 'ja', 11, '【埼玉県川越市】縁結びの神社「川越氷川神社」ですべき8つのこと', '時の鐘と蔵の街で知られる埼玉県川越市。市内中心部から北へ少し行った所に、縁結びで知られる神社「川越氷川神社」があります。絵馬のトンネルや寄り添うご神木など、川越氷川神社ならではの魅力をまとめました。

心身の穢れを流して素敵なご縁に恵まれたい、そう思ったことはありませんか？ そんな願いを叶えてくれる神社「川越氷川神社」が埼玉県川越市にあります。

本記事では、小川での人形流しや鯛のおみくじなど、川越氷川神社でこそできることをご紹介します。

約1500年も昔に創建されたと言われている川越氷川神社には、素盞鳴尊(すさのおのみこと)、奇稲田姫命(くしいなだひめのみこと)、脚摩乳命(あしなづちのみこと)、手摩乳命(てなづちのみこと)、大己貴命(おおなむちのみこと)の5柱の神様が祀られています。', '["https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123231.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123232.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123233.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123234.webp"]'::jsonb, '2017-04-21'::timestamptz),
  ('https://matcha-jp.com/jp/3842', 'ja', 11, '埼玉県に日光東照宮が!?日本三大聖天のひとつ 「妻沼聖天山」', '妻沼聖天山は、待乳山聖天（東京都）、生駒聖天（奈良県）と並ぶ、日本三大聖天の一つです。きらびやかな装飾で、埼玉日光とも呼ばれる、妻沼聖天山をご紹介します。

埼玉県熊谷市にある妻沼聖天山(めぬましょうでんざん)。待乳山聖天(東京都)、生駒聖天(奈良県)と並ぶ、日本三大聖天のひとつとして名高い寺院です。

聖天とは仏教における神様の一人で、別名・歓喜天(かんぎてん)とも呼ばれる守護神のこと。歓喜天を祀る寺院自体のことを聖天と呼ぶこともあります。

妻沼聖天山の一番の見どころは、なんといっても国宝に指定されている本殿「歓喜院聖天堂」です。世界的に有名な日光東照宮を彷彿とさせる絢爛豪華な建物で、「埼玉日光」とも呼ばれています。また、縁結びのご利益があることでも有名です。今回はそんな妻沼聖天山の見どころをご紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2017/01/18-13991.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/18-13992.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/18-13999.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/18-13993.webp"]'::jsonb, '2017-01-25'::timestamptz),
  ('https://matcha-jp.com/jp/1743', 'ja', 11, '1日中遊べる！埼玉のとっておきのショッピングスポット7選', '埼玉県にはショッピングに便利な施設が多数存在します。駅近くの大型ショッピング施設や、地元の人に大人気のアウトレットモールなどがあり、びっくりするほど多くのお店が入っています。大型のショッピングモールあちこちは回らなくても、1か所でファッションアイテムから食品やお土産などすべて揃えることができるので、いろいろ見たい観光客にはうれしいですね。そこで今回は、埼玉のショッピング情報をまとめて紹介します。

東京のすぐ北にある埼玉県は、数多くの魅力的な観光スポットがあります。埼玉ならではのグルメや体験を楽しめる場所があり、東京からのアクセスがよいところも魅力です。

グルメや体験だけではなく、埼玉県には、大型ショッピング施設や人気のアウトレットモールなど、買い物に便利な施設が多数存在します。

大型のショッピング施設には、さまざまな店舗が入っています。ファッションアイテムから食品、おみやげなどすべてを揃えることができるので、いろいろなものを買いたい観光客にはうれしい施設です。', '["https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123108.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123109.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123105.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123106.webp"]'::jsonb, '2018-11-14'::timestamptz),
  ('https://matcha-jp.com/jp/151', 'ja', 12, '早く安く行くには？成田空港への5つの行き方', '近年のLCC(ローコストキャリア)と呼ばれる、格安航空会社の増加に伴って、ますます国際空港として注目される成田空港。今回は、代表的なアクセス方法についていくつか紹介していきたいと思います。

しかし、利用する側にとって頭を悩ませるのはアクセスの問題。羽田空港と比べると、成田空港はどうしても交通面では不便に感じています。またアクセス方法も多くあるので、どれを利用するのがいいのかは悩むところ。

これは成田空港を利用する際の代表的な特急電車のひとつです。東京駅～成田空港間が約1時間という早さがポイントです。また、渋谷や新宿、八王子、横浜など停車駅が多く、首都圏からダイレクトでアクセス可能で利用しやすいのが特徴です。値段は東京→成田空港間で片道約3000円(乗車駅による)。

座席もとてもゆったりとした作りになっていて、無線LANの利用や、トランクなどの大荷物置き場にはダイヤル式の鍵が付いている点も、利用者には嬉しいところです。チケットはインターネットから簡単に購入することができます。', '["https://resources.matcha-jp.com/resize/720x2000/2022/03/29-124630.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/29-124631.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/29-124632.webp"]'::jsonb, '2017-04-19'::timestamptz),
  ('https://matcha-jp.com/jp/5968', 'ja', 12, '東京ディズニーシーで食べたい！オススメ食べ歩きスナック7選', '東京ディズニーリゾートの楽しみの1つが食べ歩き。ここでは東京ディズニーシーのオススメ食べ歩きスナック＆スイーツをまとめてご紹介。かわいい形のスナックやビールに合うギョウザドッグ、限定フレーバーのチュロスまで、東京ディズニーシーを味わいつくそう！

パーク内のワゴンなどで購入でき、アトラクションの待ち時間や、ちょっと小腹が空いたときなどの強い味方です。

今回は東京ディズニーシーでの食べ歩きに最適なオススメスナック＆スイーツを7つご紹介。東京ディズニーシー限定のスナックもあるので、ここでしかできない食べ歩きを楽しみましょう！

正解は、しっぽ。アラビアンコースト内のアトラクション「シンドバッド・ストーリーブック・ヴォヤッジ」に登場する子トラ、チャンドゥのしっぽをイメージしています。食べるのがもったいないような可愛らしい形とカラフルな色合い。', '["https://resources.matcha-jp.com/resize/720x2000/2018/04/20-52705.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/09-51885.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/09-51886.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/20-52700.webp"]'::jsonb, '2018-04-27'::timestamptz),
  ('https://matcha-jp.com/jp/6869', 'ja', 12, '温泉、海鮮グルメ、絶景を堪能！成田空港から行く千葉の温泉宿4選', '温泉や海鮮グルメ、絶景が好きな方は東京近郊の千葉県がオススメ！ 千葉は温泉宿が多く、海や山に面した自然豊かな場所。新鮮な海の幸も魅力的です。今回は人気エリア別に千葉のオススメ温泉ホテルを4つ紹介。次回の日本旅行の参考にしてください。

温泉、海鮮グルメ、絶景ありの千葉県。成田空港や東京からのアクセスがよく、東京近郊旅行の旅先として定番です。

ここでは成田空港からも近い千葉県南部を中心に、人気エリアの特色ある温泉ホテルを4つ紹介します。家族や友人、恋人と一緒に旅行を考えている人は、ぜひ千葉からスタートしましょう。到着してすぐに温泉で極上のリラクゼーションを味わえますよ！

千倉温泉は房総エリアでもっとも古いと言われている温泉。鎌倉時代(1185年～1333年)の将軍、源頼朝(みなもとのよりとも)もここで疲れを癒し、回復を図ったと伝えられています。', '["https://resources.matcha-jp.com/resize/720x2000/2018/12/04-67335.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/04-67338.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/14-68081.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/17-68187.webp"]'::jsonb, '2018-12-08'::timestamptz),
  ('https://matcha-jp.com/jp/14', 'ja', 13, '原宿から渋谷に続く「キャットストリート」でおしゃれなアイテムをゲット！？', 'キャットストリートは、渋谷から原宿をつなぐ遊歩道となっており、明治通りの宮下公園付近から、渋谷区心身障害者福祉センター付近まで続く道を指します。

おしゃれなブランドの路面店や居心地の良いカフェなど、様々なお店が連なる原宿を代表する通りとなっています。

この道沿いに、日本発の多くのブランドが旗艦店を出しており、もしあなたが日本のファッションに興味があるのなら絶対に行く価値アリ！

買い物に疲れてもご安心を。キャットストリートには、お洒落で居心地の良いカフェや、遊歩道沿いの石畳など、座って休むところもあちこちに。一日中買い物を満喫できます。', '["https://resources.matcha-jp.com/resize/720x2000/2022/03/08-123641.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/08-123640.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/08-123646.webp"]'::jsonb, '2017-05-15'::timestamptz),
  ('https://matcha-jp.com/jp/16', 'ja', 13, '原宿といえばココ！「竹下通り」に原宿のすべてが詰まってる！', 'JR原宿駅を出てすぐのところにある、「竹下通り」で、日本の”原宿の文化”を学びに行ってみましょう。

JR原宿駅を出てすぐのところにある、「竹下通り」にやってきました。個性的なファッションの若者と、カラフルなお菓子やスイーツが通りを彩ります。いまや世界で活躍している「きゃりーぱみゅぱみゅ」も原宿系女子。

竹下通りは、JR原宿駅竹下口を降りて目の前に続く原宿のメインストリートです。大小さまざまなショップが立ち並び、訪日観光客や原宿に遊びに来た人々で道はぎゅうぎゅう。

竹下通りは、ファッション・雑貨・カルチャー・グルメなど、原宿の文化が全て集まっています。ここを歩けば、原宿がどのような街なのかが一目で分かるでしょう。', '["https://resources.matcha-jp.com/resize/720x2000/2022/03/28-124560.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/28-124559.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/28-124563.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/28-124569.webp"]'::jsonb, '2014-02-02'::timestamptz),
  ('https://matcha-jp.com/jp/27', 'ja', 13, '歴史と活気にあふれる商店街「アメ横」 叩き売りで、安くお買い物しちゃう？', 'JR上野駅から御徒町駅までの高架下に沿ってのびる商店街。食料品や衣服、雑貨や宝飾品などの店が所狭しと並び、豊富な品揃えと価格の安さが魅力です。正式名称は「アメ横商店街連合会」ですが、商店街の看板に表示されているように「アメ横」と呼ばれ、庶民に親しまれています。

正式名称は「アメ横商店街連合会」ですが、商店街の看板に表示されているように「アメ横」と呼ばれ、庶民に親しまれています。

第二次世界大戦後、極度の食料不足に悩む人々によって、自然発生的な闇市である「アメ横」が誕生しました。

アメリカ軍の物資が市場で手に入ったことや、砂糖を使用した飴を中心に商いをおこなう店が200軒以上あったことから「アメ横」と呼ばれるようになったと言われています。', '["https://resources.matcha-jp.com/resize/720x2000/2022/04/28-126200.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/28-126201.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/28-126202.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/28-126203.webp"]'::jsonb, '2017-05-18'::timestamptz),
  ('https://matcha-jp.com/jp/261', 'ja', 14, '【KAMAKURA】たった20円で大仏の中を探検！猫背な「鎌倉大仏」とは？', '鎌倉の観光ツアーでは欠かせないスポット。それが鎌倉大仏殿高徳院。通称「鎌倉大仏」。海から近く、山に囲まれている、そんな場所に大仏があります。

鎌倉の観光ツアーでは欠かせないスポット。 それが鎌倉大仏殿高徳院。通称「鎌倉大仏」。 海から近く、山に囲まれている、そんな場所に大仏があります。

日本における大仏とは奈良時代（西暦 745年）頃に奈良県の「東大寺」に作られたのがはじまり。その後は幸福を願うために日本各地に造立されるようになりました。

鎌倉の大仏は奈良の大仏と同様に「日本三大大仏」として、日本国内の大仏の代表とされています。', '["https://resources.matcha-jp.com/archive_files/jp/2014/05/IMG_2438_R-1024x768.webp","https://resources.matcha-jp.com/archive_files/jp/2014/05/IMG_2429_R.webp","https://resources.matcha-jp.com/archive_files/jp/2014/05/8415103437_b246272948_b.webp","https://resources.matcha-jp.com/archive_files/jp/2014/05/IMG_2444_R.webp"]'::jsonb, '2014-05-20'::timestamptz),
  ('https://matcha-jp.com/jp/1938', 'ja', 14, '江ノ島の景色を楽しみ、鎌倉大仏に会いに行こう。東京から鎌倉への行き方！', '東京から約1時間の古都・鎌倉。お寺や神社が多いことはもちろん、自然が多く落ち着いた雰囲気の街です。今回は、東京から鎌倉へのアクセス方法をご紹介します。

東京から約1時間で行ける古都・鎌倉。お寺や神社が多いことはもちろん、自然が多く落ち着いた雰囲気の街です。

花見スポットとして知られる鶴岡八幡宮や、大仏で知られる高徳寺、6月にはアジサイが咲き誇る長谷寺(はせでら)など、見どころいっぱいです。

鎌倉まで最短の時間で行くにはJR横須賀線(よこすかせん)に乗りましょう。乗り換えなしで、東京駅からは920円(57分)、品川駅からは720円(49分)で鎌倉駅まで行くことができます。', '["https://resources.matcha-jp.com/resize/720x2000/2022/07/26-128653.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/26-128654.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/26-128655.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/26-128658.webp"]'::jsonb, '2019-06-03'::timestamptz),
  ('https://matcha-jp.com/jp/1950', 'ja', 14, '東京から横浜への行き方！6つのアクセス方法、どれが安くて早いか検証してみた', '都内から横浜への行き方、一体どのくらいあるかご存知ですか？ なんと在来線だけでも、6種類の電車が横浜まで乗り換え無しで繋がっています。東京、新宿、上野、品川、渋谷、池袋から横浜までの行き方をまとめました。ぜひ、参考にしてみてくださいね。

日本3大中華街のひとつである横浜中華街や、海を眺めることのできる赤レンガ倉庫前の広場は、いつも多くの人で賑わっています。また、四季折々の植物を鑑賞できる三渓園(さんけいえん)という庭園も有名。東京から近い点も訪日観光客にとって魅力的です。

今回は、2025年1月現在における、都内から横浜駅へのオススメの行き方を紹介します。

横浜まで運行している電車は全部で6種類もあり、都内の主要な駅である東京駅、上野駅、品川駅、渋谷駅、新宿駅、池袋駅からであれば乗り換えなしで横浜駅へ行くことができます。', '["https://resources.matcha-jp.com/archive_files/jp/2016/05/9638383581_0a6fcdf1dc_k1-1024x681.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/12-125489.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/12-125491.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/12-125497.webp"]'::jsonb, '2017-05-19'::timestamptz),
  ('https://matcha-jp.com/jp/1322', 'ja', 15, '日本酒5種を500円で飲み比べできる、新潟「ぽんしゅ館」', '新潟県は日本酒の年間出荷量第3位の「日本酒の県」。新潟で日本酒を飲んでみたいという方にぜひオススメしたいのが、県日本酒を500円で飲み比べる「ぽんしゅ館」です。

新潟県は全国一の酒蔵数(※1)を誇り、日本酒の年間出荷量は日本で第3位。日本酒製造業は県を代表する産業のひとつです(出典:経済産業省「2010年 工業統計表」)。新潟にお越しの際は、ぜひおいしい日本酒を飲んでいただきたいものです。

新潟で日本酒を飲んでみたいけど、一升瓶(※2)は飲みきれない。有名な銘柄を色々飲んでみたいけど、お金はあまりない……。そんな方にぜひオススメしたいお店があります。

新潟駅構内にある「ぽんしゅ館」なら、県内92の酒造(2015年10月現在)の日本酒を500円で飲み比べることができます。', '["https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123151.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123152.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123153.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123154.webp"]'::jsonb, '2017-05-19'::timestamptz),
  ('https://matcha-jp.com/jp/1932', 'ja', 15, '【2026開催】新潟・長岡花火の予約はいつから？リセールチケット情報も解説', '新潟県長岡市で開催される「長岡まつり花火大会」は、日本の三大花火大会のひとつです。650メートルもの大輪の花火をはじめとした見どころ紹介とともに、2026年の開催日程、会場へのアクセス、有料席チケットの買い方、穴場スポット情報をまとめて解説します。

みなさんは、日本三大花火大会にも数えられる「長岡まつり花火大会」通称「長岡花火」をご存知ですか。

本記事では、8月上旬に見ることができる新潟県長岡市の長岡まつり花火大会のチケット情報を、日程・アクセス・見どころ・穴場情報とともにご紹介します。

2026年の長岡まつり大花火大会は、開催が発表されました。 開催日：2026年8月2日(日)・3日(月) 花火打ち上げ時間：19：20～21：10 詳細：長岡まつり大花火大会の公式HPをご確認ください。', '["https://resources.matcha-jp.com/resize/720x2000/2024/06/19-184097.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/22-128457.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/30-138699.webp","https://resources.matcha-jp.com/archive_files/jp/2016/03/nagaokahanabi20160302c.webp"]'::jsonb, '2016-06-03'::timestamptz),
  ('https://matcha-jp.com/jp/25331', 'ja', 15, '【関東紅葉】秋の行楽シーズン到来！関東近郊で巡る秋の絶景スポット', '秋の訪れとともに、関東近郊の山々や公園は美しい紅葉で彩られます。特に10月は、赤や黄色に色づく葉が見頃を迎え、多くの人が自然の鮮やかな景色を楽しみに訪れます。

日本では、秋になると山々や街路樹が赤や黄色に色づき、「紅葉狩り」と呼ばれる風習が古くから親しまれています。春の花見と並び、紅葉を楽しむことは季節の移ろいを感じる大切な文化のひとつです。特にカエデやイチョウが美しく色づく10月から11月にかけては、多くの人が紅葉の名所を訪れ、自然の美しさに癒されます。旅行や日帰りレジャーの目的としても人気が高く、寺社仏閣や公園、山間部ではライトアップやイベントが行われることもあります。

紅葉は単なる景色ではなく、日本人にとって「秋を味わう」大切な季節の風物詩なのです。

ところで、「紅葉」と「もみじ（楓）」の違いをご存じでしょうか？同じように使われることが多いこの二つの言葉ですが、実はそれぞれに異なる意味があるのです。', '["https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238244.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238115.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238116.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238117.webp"]'::jsonb, '2025-07-03'::timestamptz),
  ('https://matcha-jp.com/jp/2728', 'ja', 16, 'のび太やジャイアンに会える！『ドラえもん』の故郷、富山県高岡市へ', '富山県高岡市は、『ドラえもん』の作者・藤子・F・不二雄氏の故郷。市内には個性的なキャラクター達に出会える遊歩道や、アニメに出てくる空き地などがあり、ファンの聖地とも呼ばれています。

2015年の北陸新幹線開通にともない、北陸地方は瞬く間に一大観光スポットとなりました。しかし、富山県の高岡市は北陸における観光スポットという顔の他に、『ドラえもん』の作者の故郷だと言うことをみなさんは知っていますか？ この町ではマンガに出てくる空き地が再現されているだけでなく、『ドラえもん』に関する様々な観光スポットが溢れています。ドラえもん好きなら絶対に行くべき観光地です。

高岡市は富山県の西部に位置し、面積は約209.57㎢、人口は約17万人以上の、富山県内において富山市に次ぐ第2の人口を誇る都市です。日本有数の銅器の生産地である他にも、日本の三大大仏にも数えられることがある高岡大仏も、ここ高岡市にあります。そして著名な漫画家であり、人気作品『ドラえもん』を手がけた藤子·F·不二雄氏の故郷でもあります。

高岡駅前のウイング・ウイング高岡広場にある小さな散歩道。その両端にはドラえもんをはじめ他のキャラクター計12体の銅像が置かれています。', '["https://resources.matcha-jp.com/archive_files/jp/2016/09/e7a200f7d9e3e6690544bc9d1327eee9.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/b6ce0054c49f2f10562589227854beb6.webp"]'::jsonb, '2016-10-28'::timestamptz),
  ('https://matcha-jp.com/jp/23843', 'ja', 16, '富山の1~12月の最低・最高気温は？季節ごとのおすすめの服装も紹介', '「富山に行く予定があり、あらかじめ富山の気温について知っておきたい」という方もいるでしょう。そこで今回では、富山の月別の最低・最高気温や気候の特徴について解説します。季節ごとのおすすめの服装も紹介するので、富山を訪れる際は参考にしてみてください！

夏は晴れの日が多い一方で、冬は曇りや雨の日が多くなり、地域によっては豪雪に見舞われることも。

この記事では、富山の月別の最低・最高気温やおすすめの服装を紹介するので、ぜひ最後までご覧ください！

4月に入ると、気温がぐんぐん上昇し、平均気温も12℃以上に。5月には、平均最高気温も21℃を超え、春らしい陽気を感じられるようになります。', '["https://resources.matcha-jp.com/resize/720x2000/2025/01/30-221681.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/30-221682.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/30-221680.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/30-221683.webp"]'::jsonb, '2025-01-30'::timestamptz),
  ('https://matcha-jp.com/jp/24767', 'ja', 16, '立山黒部の年間気温、開通時期、おすすめ観光シーズンと服装を徹底解説！', '日本の北アルプス山脈に位置する立山黒部は、多くの観光客が憧れる秘境です。壮大な雪の大谷をはじめ、四季折々の美しい景色は、訪れる旅人に尽きない感動を与えてくれます。初めて立山黒部を訪れる方も、この絶景を存分に楽しむために、しっかりと準備をしておきましょう！この記事では、立山黒部の天気、服装、開通時期、そして注意点について詳しく解説し、あなたの完璧な旅の計画をサポートします。

富山県と長野県の県境に位置する立山黒部地域は、標高の高い北アルプス山脈に属しているため、四季の変化がはっきりしており、気候は山岳の標高によって大きく異なります。

年間を通して降水量が多く、特に冬は積雪深くに及ぶ日本有数の豪雪地帯です。夏は涼しく過ごしやすい気候で避暑に最適。春と秋は花や紅葉を楽しむ絶好のシーズンです。そして冬、11月から翌年4月にかけては、一面雪に覆われた幻想的な世界が広がります。

以下に各季節の気温、服装、注意点をまとめました。立山黒部の気候の特徴をチェックして、旅行の準備をしましょう！', '["https://resources.matcha-jp.com/resize/720x2000/2025/04/24-231949.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/16-233656.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/16-233652.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/16-233655.webp"]'::jsonb, '2025-05-16'::timestamptz),
  ('https://matcha-jp.com/jp/1109', 'ja', 17, '金沢駅の鼓門と、もてなしドームの魅力・コンセプトを紹介！', '金沢駅の兼六園口にある鼓門(つづみもん)と、もてなしドームにはそれぞれコンセプトがあります。金沢の伝統芸能を活かした鼓門、ガラスを張り巡らせた明るさと取り入れ雨に濡れないように工夫されたもてなしドーム。その魅力とコンセプトに迫ります。

城下町が今もなお残り、日本の昔を体験できる石川県。温泉街も豊富にあり、日本海に面していることから新鮮な海の幸も味わうことができるので、日本人にも人気の県の1つです。

その中でも金沢市には、金沢城や兼六園、武家屋敷や茶屋街など、当時の面影が色濃く残っていて、見どころが満載です。

その起点となる金沢駅ですが、実はここにも見ておいた方が良いスポットがあるのをご存知でしょうか。', '["https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123246.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123247.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123249.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123248.webp"]'::jsonb, '2017-05-17'::timestamptz),
  ('https://matcha-jp.com/jp/2378', 'ja', 17, '金沢市「尾山神社」〜和・漢・洋が融合した魅惑の神社〜', '北陸の小京都とも呼ばれている石川県金沢市にある金沢尾山神社。大河ドラマにも取り上げられた前田利家を祀っている神社で、和漢洋3つの様式を融合させたユニークな神社、尾山神社ついて説明しています。

石川県金沢市には北陸の小京都という呼び名があります。京都と同じくらい古い町並みや文化が残っている、金沢市だからこそつけられた呼び名です。

そんな石川県や金沢市の礎が築かれたのは、江戸時代のこと。当時の石川県は加賀藩と呼ばれ、前田家によって統治されていました。加賀前田家の初代当主が前田利家です。

金沢市内には、前田利家および加賀藩の精神を記念するため建立された尾山神社があります。和漢折衷でありながら洋式の風格も備えた、特徴的な神社である尾山神社を紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2022/04/11-125449.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/11-125450.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/11-125451.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/11-125452.webp"]'::jsonb, '2016-12-09'::timestamptz),
  ('https://matcha-jp.com/jp/11327', 'ja', 17, '石川・金沢のお土産なら、小松空港すぐの「イオンモール新小松」へ', '金沢市や加賀温泉、福井県、富山県などの北陸の観光スポットに周遊する際の拠点として便利な石川県の小松空港。その空港からバスで約20分の距離にあるのが、「イオンモール新小松」です。人気アパレル店や食品などがそろい、九谷焼といった地元の魅力に出合えるショッピングスポットです。

北陸地方に初めてできた大型ショッピングモール「イオンモール新小松」は、日本・欧米の有名ブランド店のほか、石川県小松市の生鮮商品、地元の特産品が多くそろうスポット。

建物の外観や内装に、石川県が生んだ伝統工芸・九谷焼が使われていることが特徴で、ショッピングだけでなく、観光目的の人も楽しめるでしょう！

石川県の小松空港は、台湾、中国、韓国と直行便でつながっている、北陸地方の玄関口。金沢市や加賀温泉、福井県、富山県といった北陸の観光スポット、さらに大阪をはじめとする関西地方へのアクセスも便利です。', '["https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129778.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/07-129644.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/07-129642.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/07-129643.webp"]'::jsonb, '2022-09-19'::timestamptz),
  ('https://matcha-jp.com/jp/9571', 'ja', 18, '金沢から日帰りOK！福井県で絶対に行きたい観光スポット＆グルメ13選', '北陸地方にある福井県は、絶景の東尋坊(とうじんぼう)や冬の味覚・越前(えちぜん)ガニなど、見どころ盛りだくさん！ 人気の金沢からも日帰りできるので、セットで観光するのもオススメです。今回は初めて福井県を訪れる人へ、絶対行きたい観光スポットや絶品グルメなど、モデルルートを交えてご紹介します。

日本の北陸地方にある福井県は、海に面して南北に細長く、北部と南部で方言や文化が異なります。金沢のある石川県に接する北部は、北陸地方ならではの文化が強く根づく場所。これに対して南部は京都に近く、古くから関西地方の文化の影響を受けてきました。

また、四季の移り変わりがはっきりと感じられる地域なので、季節ごとの風景の美しさはもちろん、夏はウニや牡蠣(かき)、冬にはカニやフグといった季節のおいしい食材にも恵まれています。

観光の拠点として便利なのが、各方面から列車やバスの乗り入れも多いJR福井駅です。', '["https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100842.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100846.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100847.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/01-100701.webp"]'::jsonb, '2020-03-18'::timestamptz),
  ('https://matcha-jp.com/jp/1552', 'ja', 18, '死ぬまでに行きたい！福井県でNo.1の絶景「三方五湖」', 'この記事は福井県にある「三方五湖」の魅力を紹介しています。三方五湖は福井県にある絶景スポットで、5つある湖の色が違うため、絶妙なコントラストを見ることができます。福井県にある「三方五湖」に行ってみてください。

日本には47の都道府県があり、どの都道府県にも素晴らしい観光スポットがあります。その中でも絶景と呼ばれるスポットもあり、近年多くの観光客が訪れています。

そんな中、まだまだ知られていない絶景が福井県には存在します。それが今回紹介する「三方五湖（みかたごこ）」です。電車はなく車で行くことになりますが、天気に恵まれれば素晴らしい景色を見ることができます。

低い山々の谷間にちりばめられた三方湖（みかたこ）、水月湖（すいげつこ）、菅湖（すがこ）、久々子湖（くぐしこ）、日向湖（ひるがこ）の5つの湖がかもしだす微妙な色あいは神秘的で、その美しさから国指定の名勝になっています。', '["https://resources.matcha-jp.com/resize/720x2000/2024/12/05-213761.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/05-213762.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/05-213763.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/05-213764.webp"]'::jsonb, '2016-01-13'::timestamptz),
  ('https://matcha-jp.com/jp/24196', 'ja', 18, '【福井】永平寺へのアクセス方法は？主要都市から電車・バス・車を使った行き方を解説！', '福井県にある永平寺は、日本の曹洞宗の大本山です。仏教の修行のため山中に建てられていますが、現在は交通網が整備され観光でも訪れやすくなっています。この記事では、最寄り駅からや、東京・名古屋・大阪という主要都市などからの永平寺までのアクセス方法を紹介します。

福井県吉田郡永平寺町にある「永平寺」は山号を「吉祥山」といい、神奈川県の総持寺と並んで日本の曹洞宗の大本山とされています。

建物の多くが重要文化財に指定されていて、厳かな雰囲気と美しい自然の調和が楽しめるお寺です。また、日帰りや一泊二日での参禅体験も行われています。

この記事では、東京、名古屋、大阪という主要都市から、永平寺までのアクセス方法を紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225256.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/21-225399.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/21-225400.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/21-225401.webp"]'::jsonb, '2025-02-20'::timestamptz),
  ('https://matcha-jp.com/jp/7034', 'ja', 19, '新宿から富士山・河口湖へ直通！特急「富士回遊」に乗るべき3つの理由', '2019年3月16日、新宿からダイレクトで富士山、河口湖へ行ける特急「富士回遊」が運行開始！ 河口湖や富士急ハイランドなど沿線の見どころからチケットの買い方まで、特急「富士回遊」の魅力を詳しくご紹介します！

日本に旅行に来たら、一度は行ってみたい場所、富士山。その富士山まで、東京の新宿駅からダイレクトで行ける特急「富士回遊」。

特急「富士回遊」は、新宿からJR中央線・富士急行線を経由し、富士山や河口湖まで乗り換えなしで行ける特急列車。

富士山・河口湖エリアへ行くなら絶対に特急「富士回遊」がオススメ。その理由を、3つにわけてご紹介しましょう！', '["https://resources.matcha-jp.com/resize/720x2000/2019/02/12-71152.webp","https://resources.matcha-jp.com/resize/720x2000/2019/02/04-70551.webp","https://resources.matcha-jp.com/resize/720x2000/2019/02/04-70535.webp","https://resources.matcha-jp.com/resize/720x2000/2019/02/04-70536.webp"]'::jsonb, '2019-02-01'::timestamptz),
  ('https://matcha-jp.com/jp/10362', 'ja', 19, '天空にいちばん近い列車！小海線で行く、四季の絶景と星空に出会う旅', 'JR線で「標高の一番高い場所を走る鉄道」として知られる小海(こうみ)線。長野県の小諸駅と山梨県の小淵沢駅をむすぶ路線です。名前に「海」という字がついていますが、この鉄道の見どころは山！ 都会の観光では味わえない自然美を求めて、高原の鉄道旅に出発しましょう。

小海線は、長野県の小諸(こもろ)駅と山梨県の小淵沢(こぶちざわ)駅をつなぐ、全長78.9キロの路線です。標高1000メートルを超える駅がいくつもあり、車窓からは富士山や八ヶ岳など、日本有数の山々が望めます。

近くには人気観光地の軽井沢があり、軽井沢駅から小諸駅まではしなの鉄道で約30分の道のりです。

ちなみに、「海」という字がついた鉄道ですが、近くに海はありません。それどころか、沿線には「日本で海から一番遠い地点」(長野県佐久市内)があるほど。', '["https://resources.matcha-jp.com/resize/720x2000/2021/01/21-111857.webp","https://resources.matcha-jp.com/resize/720x2000/2021/01/21-111845.webp","https://resources.matcha-jp.com/resize/720x2000/2021/01/21-111846.webp","https://resources.matcha-jp.com/resize/720x2000/2021/01/21-111847.webp"]'::jsonb, '2021-01-21'::timestamptz),
  ('https://matcha-jp.com/jp/11029', 'ja', 19, '【東京近郊】大自然を独り占め！車なしで行ける関東のグランピング場9選', '関東のグランピング施設には、車なしでも電車で気軽にアクセスできるスポットがたくさん！ この記事では、筆者が実際に滞在したことのある施設も含めて、東京近郊でアクセスしやすい「関東のグランピングスポット9選」をご紹介！ 富士山を眺めたり、おしゃれなテントに泊まれる人気のスポットが盛り沢山です。

妙義グリーンホテル/Picture courtesy of Booking.com アウトドア初心者でも、気軽に自然と触れ合えるのが魅力の「グランピング」。

東京近郊の関東エリアには、電車やバスなどの公共交通機関だけで簡単にアクセスできるグランピング施設があります。

そこで今回は、都内から車なしでアクセスできる「関東のグランピング施設9選」をお届け！ 富士山の絶景や全客室温泉付きのオススメグランピング施設などを、ぜひチェックしてみてくださいね。', '["https://resources.matcha-jp.com/resize/720x2000/2024/07/10-187450.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/17-120731.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/06-60000.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/06-59999.webp"]'::jsonb, '2022-03-01'::timestamptz),
  ('https://matcha-jp.com/jp/8105', 'ja', 20, '東京からの日帰り旅にぴったり！長野・蓼科で自然を味わえる6スポット', '長野県の蓼科は、標高1,000メートル以上の風光明媚な高原です。東京から特急で2時間でアクセスでき、日帰り旅行にもぴったり。JR茅野駅からバスで行けるスポットが多く、車が苦手な人も安心です！ 蓼科で美しい自然が楽しめるオススメ6スポットを紹介します。

雄大な自然が広がる長野県は、東京から1泊、あるいは日帰り旅行にぴったりの場所。長野県には、軽井沢や上高地といった素敵なハイキングスポットが多くあります。中でも日帰りで自然を味わうには、東京・新宿から特急で2時間で行ける蓼科高原がオススメです。

本記事では、数ある蓼科高原の見どころの中から、JR茅野駅からバスで回れる6スポットを紹介します。これらのスポットは、車に乗れない、あるいは車が苦手な人も気軽に楽しめますよ。

6スポットのうち、横谷(よこや)渓谷の周辺にある御射鹿池(みしゃかいけ)と横谷峡遊歩道、乙女滝、横谷観音展望台は遊歩道でつながっています。一緒に回るのもオススメですよ。', '["https://resources.matcha-jp.com/resize/720x2000/2019/10/13-88141.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/13-88142.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/13-88143.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/13-88144.webp"]'::jsonb, '2019-10-13'::timestamptz),
  ('https://matcha-jp.com/jp/6281', 'ja', 20, '軽井沢旅行をもっと楽しくするポイント5点！～レンタサイクル、天気など～', '人気の観光スポット軽井沢は、日本人の避暑地としてだけではなく、冬には多くの観光客がスキーに訪れる観光地です。軽井沢旅行を計画中の人に、5つのポイントをお伝えします。注意点さえ知っていれば、より楽しく過ごせるはずです！

夏の避暑地として有名な、長野県の軽井沢。綺麗な自然はもちろん、木製のおしゃれな教会、おみやげ店の集まる通り、アウトレットモールなど、観光にぴったりのスポットがたくさんあります。

普通に旅行してももちろん楽しめますが、今回は軽井沢をより楽しんでもらうためのポイントを5つ紹介します。

軽井沢のベストシーズンは？ 移動手段はどうする？ 旧軽井沢銀座通りのトイレは有料？ など、軽井沢を訪れる前に1度目を通しておきましょう！', '["https://resources.matcha-jp.com/resize/720x2000/2018/07/03-57614.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/03-57628.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/03-57632.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/03-57608.webp"]'::jsonb, '2018-09-14'::timestamptz),
  ('https://matcha-jp.com/jp/7485', 'ja', 20, '「軽井沢星野エリア ハルニレテラス」とその周辺で楽しめる8つのこと', '軽井沢の星野エリアにある「ハルニレテラス」には居心地の良いカフェや地元の商品を扱う店が並び、軽井沢に暮らしている気分で過ごせます。オススメの店やグルメ、アクティビティをまとめてご紹介します。

「ハルニレテラス」は訪れた人が地元のゆったりとした暮らしや自然の豊かさを楽しめる場所として、軽井沢星野エリア内につくられました。2009年のオープン以来、軽井沢の人気観光スポットとなっています。

「ハルニレ」とは春楡の木のこと。施設は春楡が豊かに生い茂る川辺に建っています。地面から2メートルほどの高さに設置されたウッドデッキ上に店が並んでいるため、樹々の間を歩いているような感覚で散歩ができます。

テラス全体が緑に囲まれ、そばを流れる湯川の清浄な水音に満たされた気持ちのよい場所です。', '["https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78860.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/29-78163.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/13-79486.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/29-78112.webp"]'::jsonb, '2019-06-05'::timestamptz),
  ('https://matcha-jp.com/jp/7252', 'ja', 21, '高山から日帰り！ロープウェイで行く北アルプスと温泉の贅沢旅', 'MATCHA編集部は、高山発のバスに乗って北アルプスの絶景を眺める日帰りの旅を取材。日本唯一の2F建てロープウェイ「新穂高ロープウェイ」で山頂に行き、雪化粧の山々、雪景色を望みます。飛騨豚と飛騨牛に舌鼓を打ち、温泉に入る豪華モデルコースを紹介します！

岐阜県の高山市は、歴史ある町並みで人気の観光地。高山からはバスに乗って、世界遺産に登録されている白川郷の合掌村へ日帰りで訪れることができます。

冬に雪で白く覆われる合掌村の景色は必見ですが、この美しさに負けないのが、奥飛騨にある雪化粧を施した北アルプスの山々。北アルプスは高山の東北に位置する山脈で、飛騨山脈とも呼ばれ、絶景で知られています。

高山へ行く人は、名古屋からバスで行くのが便利です。名古屋に近い空港セントレア(中部国際空港)は、バンコクや台北、香港、ソウルからの直行便もあるので、高山旅行ではセントレアを利用するとよいでしょう。セントレアから高山までは、電車、バスを乗り継いで3時間ほどです。', '["https://resources.matcha-jp.com/resize/720x2000/2019/04/18-75514.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/18-75515.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/18-75516.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/22-75738.webp"]'::jsonb, '2019-04-27'::timestamptz),
  ('https://matcha-jp.com/jp/3720', 'ja', 21, '【岐阜県】油揚げをお供えして幸運を！ 千代保稲荷神社へ行こう', '岐阜県海津市の千代保稲荷神社は、地元の人から「おちょぼさん」と呼ばれる地域で愛されている神社。一番の特徴は参拝の際に小銭と一緒に油揚げをお供えすること。本記事ではそんな千代保稲荷神社と、周辺のオススメ施設の紹介をしています。

伏見稲荷大社や伊勢神宮、出雲大社などの有名神社もいいですが、日本にはその他にも各地にユニークな神社があります。

今回紹介するのは、岐阜県海津市(かいづし)の千代保稲荷神社(ちよぼいなりじんじゃ)です。いったいこの神社は他の神社とどこが違うのか？ 一緒に見ていきましょう！

千代保稲荷神社は、地元の人からはおちょぼさんと呼ばれ、親しまれている神社です。千代保稲荷神社が祀っているのは、食糧を司る神とされる稲荷大神。人々は昔、穀物の豊作を祈るためこの神社にやってきましたが、今では事業や商売の繁盛をお祈りする人がほとんどです。', '["https://resources.matcha-jp.com/resize/720x2000/2016/12/14-11649.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/14-11650.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/14-11651.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/14-11652.webp"]'::jsonb, '2017-02-22'::timestamptz),
  ('https://matcha-jp.com/jp/4436', 'ja', 21, '夏の風物詩「鵜飼い」とは？鵜飼いが見られるスポット5選〜期間、料金など〜', '「鵜飼い(うかい)」とは、鵜と呼ばれる鳥を使って川魚の鮎をとる日本古来の漁業です。岐阜県の長良川、愛媛県大洲市の肱川、大分県の三隅川が日本三大鵜飼いです。鵜飼いとはどんな漁法か、どこで見られるか(季節、料金など)を紹介します。

「鵜飼い(うかい)」とは、日本に生息するカツオドリ目ウ科の鳥「鵜(う)」を使って魚を獲る伝統的漁業で、5月〜9月に行われます。

鵜には、捕らえた魚を喉にためて吐きだす習性があり、この習性を利用して鵜飼いでは鵜に鮎(あゆ,sweet fish)を獲らせ、それを人間が吐きださせるという手法をとっています。

鵜飼いは、1〜3人の人と5～12羽の鵜によって行われます。夜、川に舟を出し、舟先の篝火(かがりび)で水面を照らして鮎を驚かせ、動きが鈍った鮎を鵜が捕らえるのです。', '["https://resources.matcha-jp.com/resize/720x2000/2017/05/18-26698.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/18-26696.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/23-26996.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/18-26699.webp"]'::jsonb, '2017-07-20'::timestamptz),
  ('https://matcha-jp.com/jp/7133', 'ja', 22, 'トロッコ列車で静岡の絶景へ。湖に浮かぶ秘境「奥大井湖上駅」', '静岡県の中部、奥大井の秘境・奥大井湖上駅を尋ねました。山に囲まれたエメラルドグリーンの湖にポツンと浮かぶ半島、そこに佇む奥大井湖上駅や周辺の様子はまさに絶景！ 普通鉄道日本一の急こう配を登る南アルプスあぷとラインの乗車レポートとともに紹介します。

東京と大阪の中間にある静岡県は、伊豆や熱海などの温泉地、富士山、浜松城など多くの観光地がある県です。

そんな静岡県の中部で、インスタ映えする景勝地として、近年人気を集めているのが「奥大井湖上(おくおおいこじょう)駅」。南アルプスの山間部へとつながる奥大井エリアにあります。

奥大井湖上駅へは、大井川鐵道「南アルプスあぷとライン」(井川線)と呼ばれるトロッコ列車で行きます。今回は列車に乗車した様子や駅からの絶景、奥大井の魅力を紹介します！', '["https://resources.matcha-jp.com/resize/720x2000/2019/03/28-73899.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/02-72310.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/02-72308.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/02-72296.webp"]'::jsonb, '2019-03-02'::timestamptz),
  ('https://matcha-jp.com/jp/3876', 'ja', 22, '熱海の定番のおみやげ！人気の温泉まんじゅう8選', '東京から日帰りで行ける温泉地、また海水浴を楽しめるリゾート地として人気の熱海。熱海に行ったら買いたいおみやげを、熱海名物の温泉まんじゅうを中心に紹介しています。

東京から日帰りできる温泉地、また海水浴を楽しめるリゾート地として知られる熱海。そんな熱海のおみやげの定番といえば、温泉まんじゅうです。

まんじゅうとは、生地の中に餡(あん)が入った和菓子のこと。温泉まんじゅうとは厳密にいうと温泉の蒸気で蒸したまんじゅうのことですが、広義には温泉地で売られているまんじゅうのことをいいます。熱海にはたくさんの種類の温泉まんじゅうがあり、定番のおみやげとしてホテルや旅館、商店街などで販売されています。

今回は熱海の定番のおみやげとして、温泉まんじゅうのなかで人気のある商品を紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2017/01/31-16090.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/01-16426.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/01-16427.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/01-16428.webp"]'::jsonb, '2017-02-02'::timestamptz),
  ('https://matcha-jp.com/jp/10255', 'ja', 22, '東京・名古屋から浜松へ。必訪スポットと名物グルメを1泊2日で満喫', '東京や名古屋から新幹線で行ける静岡県の都市・浜松。花々の楽園「はままつフラワーパーク」や世界中の楽器を展示した「浜松楽器博物館」など見どころ豊富です。浜松の楽しみ方と、うなぎや餃子などのグルメを紹介！

静岡県の中心的な都市・浜松市。東京や名古屋からは新幹線で訪れることができます。浜松に到着したら、電車やバスに乗って周辺の観光地を巡りましょう。

浜松には自然や歴史、音楽、テクノロジーに関連したさまざまなスポットがあります。浜松餃子をはじめとした名物グルメも外せません！

東京駅と品川駅の2駅から浜松駅までは東海道新幹線が運行しています。どちらの駅から乗っても料金は同じ。乗車時間は最短で1時間24分です。', '["https://resources.matcha-jp.com/resize/720x2000/2020/12/02-110205.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/02-110228.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/02-110229.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/02-110206.webp"]'::jsonb, '2020-12-07'::timestamptz),
  ('https://matcha-jp.com/jp/4441', 'ja', 23, '【名古屋駅周辺】モーニング可能な喫茶店や銭湯など、夜行バス利用時の便利スポットまとめ', '深夜や早朝に発着する夜行バス。移動は安くて便利だけど、乗車前後にゆっくり待機できる場所が少ないのも悩み。今回は、早朝、深夜でも営業している名古屋駅周辺のスポットをご紹介します。

日本国内を旅行する際、安くて便利な移動手段と言えば「夜行バス」でしょう。しかし、夜に出発し翌早朝に到着という便が多いため、他の交通手段と比べると体力を消耗しがち。さらに到着しても周囲で営業している店舗が少ないため、ひと休みする場所を探すのもひと苦労です。

今回は名古屋駅周辺で、早朝、深夜でも営業しているスポットをご紹介します。到着後の休憩に使えるカフェ、出発までの準備に使えるインターネットカフェ、のんびりくつろげる銭湯施設などをまとめました。

全国チェーンのファストフード店だけでなく、モーニングサービス(以下：モーニング)を取り入れた喫茶店が多いのも名古屋の特徴です。モーニングを食べて、“名古屋の朝”を満喫するのもいいかもしれません。', '["https://resources.matcha-jp.com/resize/720x2000/2017/05/17-26647.webp"]'::jsonb, '2017-06-01'::timestamptz),
  ('https://matcha-jp.com/jp/6436', 'ja', 23, '名古屋のおすすめ観光&グルメスポットまとめ！ジブリパークやホテル情報も', '名古屋は日本3大都市のうちのひとつ。名古屋城や徳川園などの歴史的スポットから、親子で遊べるレゴランド・ジャパンなど見どころが多く、世界から注目が集まる「ジブリパーク」も近くです。オススメの観光スポットからグルメ、ホテルまでまとめて紹介します！

名古屋市観光マップ by Map-It マップイット | 地図素材サイト 東京と大阪に次ぐ大都市で、日本のちょうど真ん中あたりに位置する名古屋。「トヨタ自動車」の本社や、人気のお城・名古屋城があることで知られる愛知県の中心都市です。

大人気の「ジブリパーク」も、名古屋中心部から電車で約1時間と近い距離にあり、名古屋観光で訪れる観光客も増えてきました。

名古屋は、比較的中心部に観光スポットが固まっているものの、郊外や市外にも穴場となるような観光スポットがあります。', '["https://resources.matcha-jp.com/resize/720x2000/2025/06/04-235503.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/28-61398.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/28-133395.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/26-61341.webp"]'::jsonb, '2019-02-18'::timestamptz),
  ('https://matcha-jp.com/jp/7258', 'ja', 23, '【名古屋】市場、朝市、商店街！ローカルな穴場とグルメを巡る旅', '大都市・名古屋にも、朝市や商店街、市場など、ローカルな雰囲気を楽しめる場所があります。今回は、地元の方がショッピングをする商店街や、街の人気グルメ、老舗の喫茶店の名物メニューなど、名古屋の人情味が味わえるスポットを紹介します！

本記事では、市場で海の幸を食べたり、朝市で手作りの小物を探したり、賑やかな商店街でグルメを味わったりといった、いつもと違う名古屋の楽しみ方を紹介。リアルな名古屋を体験しましょう！

名古屋駅から徒歩10分ほどの「柳橋中央市場 マルナカ食品センター」。4000坪ほどの敷地に300あまりの店舗があり、魚介類、野菜、海苔、調理器具がそろう、日本屈指の規模を誇る民間の市場です。

市場は、プロの料理人に新鮮な食材を提供しているほか、一般のお客も大歓迎。手ごろな価格でその日に捕れた新鮮な海鮮類が買えます。', '["https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74421.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74422.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74400.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74406.webp"]'::jsonb, '2019-04-11'::timestamptz),
  ('https://matcha-jp.com/jp/21967', 'ja', 24, '伊勢神宮へ東京・大阪から安く・早く行くには？お得なアクセス情報も紹介', 'この記事では、東京や大阪から伊勢神宮へ安く、かつ早く行く方法を紹介します。バス、新幹線などのアクセス方法や、内宮・外宮の最寄り駅、お得な切符の情報などをご紹介します。ぜひ参考にしてみてください。

この記事では、東京や大阪から伊勢神宮へのアクセス方法を分かりやすく解説します。記事の最後には、お得情報もあわせて紹介するので、ぜひ最後までご覧ください！

東京から伊勢神宮に行く場合、もっとも早いのは飛行機、もっとも安いのは高速バスです。

一方で、大阪から伊勢神宮に行く場合は、もっとも早いのはレンタカー、もっとも安いのは高速バスになります。', '["https://resources.matcha-jp.com/resize/720x2000/2024/10/16-202934.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/08-201378.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/08-201379.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/08-201380.webp"]'::jsonb, '2024-10-07'::timestamptz),
  ('https://matcha-jp.com/jp/23760', 'ja', 24, '熊野古道のモデルコース(1泊2日)｜初心者～中級者まで楽しめるルートを紹介', '熊野古道は熊野三山の巡礼道で、ユネスコの世界遺産に認定されています。熊野古道を1泊2日で巡るモデルコースを、初心者・中級者のレベル別で3ルートを紹介。また、熊野本宮大社や湯の峰温泉のみどころ、熊野古道に関するよくある質問にもお答えします。

熊野古道は2004年にユネスコ世界文化遺産に登録され、世界的にも有名になった巡礼道です。熊野本宮大社や世界遺産「つぼ湯」が人気の湯の峰温泉があり、見どころはたっぷり！本記事では1泊2日のモデルコースを、難易度別に3ルートご紹介します。

熊野古道の参詣道は、出発点や通る場所によって、実は以下の5つのルートに分かれています。

・紀伊路(きいじ)：大阪から和歌山県田辺市までのびる南北ルート ・大辺路(おおへち)：田辺市から紀伊半島南部の海沿いを通るルート ・中辺路(なかへち)：田辺市から紀伊半島を横断するルート ・小辺路(こへち)：高野山と熊野本宮大社を最短で結ぶ山越えルート ・伊勢路(いせじ)：紀伊半島東側を通り伊勢神宮と熊野三山を結ぶ参詣ルート', '["https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220742.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220743.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220738.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220744.webp"]'::jsonb, '2025-01-23'::timestamptz),
  ('https://matcha-jp.com/jp/27308', 'ja', 24, '鳥羽水族館へのアクセス完全ガイド！電車・車・飛行機の行き方を徹底解説', '鳥羽水族館へのアクセスを徹底解説。鳥羽駅から徒歩何分か、電車・車・バス・飛行機での行き方、名古屋・大阪・東京からの所要時間を紹介。駐車場情報も掲載しているので、旅行前の確認に役立ちます。

公共交通機関の電車と飛行機、そして自家用車やレンタカーなどでの移動が多く見られます。

最寄駅はJR・近鉄「鳥羽駅」となり、水族館までは歩いて10分の距離。電車や飛行機でアクセスする場合、まずは鳥羽駅を目指すと良いでしょう。

KKdayでは、利用当日までキャンセル無料のチケット販売をしています。子どもの体調不良や急な用事などが心配でも、チケットの確保ができる嬉しいサービスです。', '["https://resources.matcha-jp.com/resize/720x2000/2026/06/23-265861.webp","https://resources.matcha-jp.com/resize/720x2000/2026/06/23-265855.webp","https://resources.matcha-jp.com/resize/720x2000/2026/06/23-265852.webp","https://resources.matcha-jp.com/resize/720x2000/2026/06/23-265854.webp"]'::jsonb, '2026-06-20'::timestamptz),
  ('https://matcha-jp.com/jp/7913', 'ja', 25, '大阪・京都にも近い滋賀のスポット・祭り・グルメなどまとめ', '大阪や京都からのアクセスが抜群な滋賀県は、雄大な琵琶湖や歴史ある街並みが楽しめる県。自然を生かしたアクティビティも豊富です。滋賀県のオススメのスポットや祭り、グルメを紹介します。

関西地方の滋賀県は、大阪や京都からアクセス抜群のエリアです。大阪からは電車で約40分、京都からは約10分。大阪・京都観光の際に滋賀まで足を伸ばしたり、滋賀県を関西観光の拠点にするのもオススメです。

県内には日本最大の湖・琵琶湖があります。周辺では、豊かな自然を活かしたアクティビティを体験可能。豪華絢爛な曳山(祭りの山車)が出される大津祭や長浜曳山まつりも必見です。

滋賀県と聞いて、日本人がまず最初に思い浮かべるのが琵琶湖。日本最大の面積と貯水量をもつ湖です。そんな琵琶湖のイチオシのビュースポットは2つ。', '["https://resources.matcha-jp.com/resize/720x2000/2019/09/10-85613.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/10-85614.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/10-85615.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/10-85616.webp"]'::jsonb, '2019-09-10'::timestamptz),
  ('https://matcha-jp.com/jp/19260', 'ja', 25, '【2025最新】関西の穴場観光スポット15選！地元ライターが厳選～ゴールデンウィークにもおすすめ', '大阪、京都、兵庫、滋賀の関西エリアから、観光客であまり混み合わないと評判の穴場の観光スポットを15ヵ所ご紹介します！ ゴールデンウィークやシルバーウィークといった大型連休のお出かけ先にもおすすめです。

都会や有名観光地から少し足を延ばせば、ゆったり過ごせるスポットは意外と多いものです。有名なお寺や観光スポットでも、予約できるところを選べば見学はスムーズ！

この記事では、関西圏在住のライターや、大阪在住のMATCHAが選んだ穴場スポットをご紹介しますので、ぜひ参考にしてみてください。

大阪のシンボルともいえる「太陽の塔」があることで有名ですが、実は大阪市ではなくお隣の吹田市にあり、大阪市内の混雑を避けることができます。', '["https://resources.matcha-jp.com/resize/720x2000/2025/04/23-231833.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/01-175852.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/01-175853.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/01-175854.webp"]'::jsonb, '2024-04-01'::timestamptz),
  ('https://matcha-jp.com/jp/9308', 'ja', 25, '【2025】関西で人気！大型アウトレット・ショッピングモール9選｜大阪からも良アクセス！', '大阪を中心とする関西エリアでは、買い物が楽しめる大型アウトレットやショッピングモールがたくさんあります。本記事では、大阪からのアクセスも良好な、アウトレットとショッピングモールを9店舗紹介。各店舗で注目したいオススメブランドやアクセス、最新情報もお届けします！

関西エリアには、心斎橋筋商店街や梅田のデパート群がある大阪をはじめ、買い物を楽しめるスポットがたくさんあります。

そこで今回は、関西で人気の大型アウトレットとショッピングモールを全部で9店舗紹介します！ お買い得な商品が豊富にそろう店から、大阪市内からアクセスしやすい店までお届けするので、関西で買物をする予定がある方はぜひチェックしてみてください。

関西のアウトレットとショッピングモールは、街の中心部ではなく郊外にあることが一般的です。', '["https://resources.matcha-jp.com/resize/720x2000/2020/04/01-100701.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/13-133733.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/22-95575.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/24-134033.webp"]'::jsonb, '2020-01-27'::timestamptz),
  ('https://matcha-jp.com/jp/236', 'ja', 26, '願い事がひとつだけ叶う。京都・嵐山の「鈴虫寺」で和尚さんの説法に肖る', '京都の静かなお寺を訪れたい方には必見！嵐山にある鈴虫寺の見どころを紹介しています。

京都駅から市バスで40分。碁盤の目の道すがら数々の神社仏閣を通り過ぎつつ、何度でも足を運びたくなるお寺が京都の嵐山にあります。

市バスで「松尾大社駅」に降り立ったあとは、住宅地の中の細道を、手作りの看板だけを頼りに向かいます。

途中、分かれ道になって、どちらへ行こうか立ち尽くしていたところへ「鈴虫寺はあっちだよ。」と自転車に乗ったおじいちゃんに教えてもらったりしながら、ゆるやかな坂道を登ってたどり着きました。', '["https://resources.matcha-jp.com/resize/720x2000/2022/05/23-127028.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/23-127029.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/23-127030.webp"]'::jsonb, '2014-05-09'::timestamptz),
  ('https://matcha-jp.com/jp/284', 'ja', 26, '伏見稲荷大社の観光にかかる所要時間は？押さえたい見どころ、ハイキング情報も紹介', '「伏見稲荷大社」は、京都駅から約10分でアクセスできる京都の名所の1つ。そんな伏見稲荷大社の観光にかかる所要時間やルート、おすすめの参拝時間、稲荷山のハイキングにかかる時間や注意事項、さらに見どころや歴史まで紹介します。

「稲荷神社」とは、日本の神の一つ「稲荷神」をお祀りしている神社です。五穀豊穣(※1)から商売繁盛、地域によっては安産や万病平癒(※2)、合格祈願(※3)までご利益があるという、まさに私達庶民の味方の神様をお祀りしている場所なのです。

※1：五穀豊穣......穀物などの農作物が平年より多く収穫できることを幅広く指す言葉。 ※2：万病平癒......様々な病気やけがが完全に治ること。 ※3：合格祈願......学業の目的が達成されるように、神仏に祈り願うこと。

日本人にとって、最も身近な神社といえる「稲荷神社」。その「稲荷神社」の総本宮が、京都にある「伏見稲荷大社」です。', '["https://resources.matcha-jp.com/resize/720x2000/2023/04/11-136951.webp","https://resources.matcha-jp.com/resize/720x2000/2023/04/10-136837.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/14-122638.webp","https://resources.matcha-jp.com/archive_files/jp/2014/05/8202185497_e968cf5f67_b.webp"]'::jsonb, '2014-06-01'::timestamptz),
  ('https://matcha-jp.com/jp/359', 'ja', 26, '【2026最新】日本三大祭りの1つ「祇園祭」ガイド！日程・アクセスは？各日の行事、山鉾巡回ルート、見どころを徹底解説！', '2026年も京都で開催される「祇園祭」は、1000年を超える歴史を持つ、伝統ある京都の夏の風物詩。京都の街がまるごとステージとなる大規模なまつりです。祇園祭の2026年開催日程、アクセス(最寄り駅)、見どころや魅力を解説します。

毎年7月、京都で開催される「祇園祭」は、大阪の天神祭、東京の神田祭とともに日本三大祭りに数えられるまつりです。

2009年にはユネスコの無形文化遺産に登録され、街のど真ん中を練り歩く巨大な「山鉾(やまほこ)」は、京都の夏の風物詩といえます。

祇園祭はそもそも、「八坂神社」のおまつりです。その始まりは、なんと1000年以上前の869年！', '["https://resources.matcha-jp.com/resize/720x2000/2018/05/30-55254.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/15-231053.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/31-55300.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/30-55256.webp"]'::jsonb, '2018-06-01'::timestamptz),
  ('https://matcha-jp.com/jp/175', 'ja', 27, '大阪弁の有名フレーズ6選。めっちゃ便利な言葉で大阪をエンジョイ', '大阪弁は関西弁の一つであり、京都弁や神戸弁とも似ています。とにかくリアクションが大きく早口で、テンポよくたたみかける言葉です。今回は、実際に大阪を訪れたときに使える大阪弁を紹介します。

地方から首都圏に出てくると、ほとんどの人が標準語を使うようになるかと思いますが、大阪人は全国どこに行っても、ときには海外でも大阪弁を使う人が多いのです。たかが方言、されど方言。大阪人の大阪弁に対する情熱は、きっとあなたの想像以上です。

めっちゃ好き。めっちゃ良い。めっちゃかっこいい。めっちゃ似合う。めっちゃおいしい……。特に、相手を褒めるときなど語頭に「めっちゃ」とつけてみて下さい。相手は2倍も3倍も喜びます。

こちらは大阪弁の代名詞。「なんでやねん」を無理矢理標準語にするとならば「どうしてそうなるんですか？」。相手に「つっこみ(Tsukkomi)」をいれるときに使う言葉です。', '["https://resources.matcha-jp.com/resize/720x2000/2023/03/02-135190.webp"]'::jsonb, '2014-04-16'::timestamptz),
  ('https://matcha-jp.com/jp/292', 'ja', 27, '大阪のシンボル「通天閣」でやりたい7つのこと〜展望台、ビリケンさん、新世界〜', '大阪の街を見守る、高さ108メートルの展望塔「通天閣」。本記事では、大阪のシンボルとも言える通天閣を徹底ガイドします。展望台、ビリケンさん、おみやげなどをチェックしましょう。

大阪には、大阪城、道頓堀などさまざまな観光スポットがありますが、多くの日本人が思い浮かべる“大阪のシンボル”が、「通天閣」でしょう。高さ108メートルの展望塔です。

通天閣があるのは、「新世界」と呼ばれる大阪の有名な観光地エリア。難波や心斎橋からも近く、電車を使うと15分程度で移動できるので、同じ日に回ることもできます。通天閣に何があるのか、何ができるのか。通天閣の魅力をさまざまな角度からご紹介します。

通天閣展望台への入り口 Picture courtesy of 通天閣観光株式会社', '["https://resources.matcha-jp.com/resize/720x2000/2018/06/25-57044.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/25-57047.webp","https://resources.matcha-jp.com/archive_files/jp/2014/05/DSC_1428.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123699.webp"]'::jsonb, '2018-06-26'::timestamptz),
  ('https://matcha-jp.com/jp/527', 'ja', 27, 'JR大阪駅から梅田駅への最短ルートは？徒歩での行き方や出口を写真付きで解説', '大阪には「梅田駅」という名前のついた駅がいくつもあります。日本人でも複雑で迷ってしまう“ダンジョン”、梅田地下街。JR大阪駅からそれぞれの梅田駅への行き方を、写真つきでわかりやすく解説。この記事を見れば、もう梅田で迷わない！

梅田駅・大阪駅/Photo by Pixta 「梅田駅」と「大阪駅」は、同じ位置にありながら名前が異なる、関西最大のターミナル駅です。

電車の路線によって駅名が違い、JRのみ「大阪駅」という名前がついています。それ以外は、以下の通り"梅田"と名のつく駅は、5つもあります！

▼5つの梅田駅 ・大阪メトロ御堂筋線「梅田駅」 ・阪急電鉄「大阪梅田駅」 ・阪神電鉄「大阪梅田駅」 ・大阪メトロ四つ橋線「西梅田駅」 ・大阪メトロ谷町線「東梅田駅」', '["https://resources.matcha-jp.com/resize/720x2000/2024/05/08-179106.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/28-121792.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/06-59980.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/06-59981.webp"]'::jsonb, '2018-08-13'::timestamptz),
  ('https://matcha-jp.com/jp/2523', 'ja', 28, '日本三大夜景のひとつ！神戸の「摩耶山掬星台」への行き方', '日本には日本三大夜景と言われる美しい夜景が3つ存在します。特に兵庫県神戸市・掬星台からの夜景はデートスポットとしても有名。今回は、神戸の中心地・三宮からの掬星台へのアクセス方法をご紹介します。

日本には日本三大夜景と言われる美しい夜景が3つ存在します。北海道・函館山からの夜景、長崎県・稲佐山からの夜景、そして、兵庫県神戸市の「摩耶山掬星台(まやさんきくせいだい)」から観る、神戸の街の夜景です。

特に、掬星台からの夜景はデートスポットとしても有名で、神戸市中心部からのアクセスも簡単なので人気が高いポイントです。

三宮から掬星台へ行くには、基本的にバスとケーブルカーとロープウェーに乗る必要があります。そのため、まずはバス乗り場へ向かいましょう。', '["https://resources.matcha-jp.com/resize/720x2000/2022/01/11-120016.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/11-120029.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/11-120030.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/11-120031.webp"]'::jsonb, '2017-04-17'::timestamptz),
  ('https://matcha-jp.com/jp/2742', 'ja', 28, '神戸へ大阪からのアクセス、最安・最速で便利なのは？（バス・電車・新幹線比較）', '日本有数の港町神戸。三ノ宮エリアを中心とする繁華街は、ショッピングにうってつけ。日本3大和牛のひとつである神戸牛など、グルメも充実しています。近隣の大都市である大阪から神戸へのアクセス方法をまとめました。

実はこの神戸、大人気の観光スポット・大阪からたったの30分で行くことができるのです。大阪を旅行する際は、ぜひ併せて周遊してほしい場所です。

この記事では、大阪から神戸への行き方を紹介します。各路線でかかる時間や料金を比較しているので、ぜひチェックしてくださいね！

大阪から神戸へは、JR、阪急電鉄、阪神電車といった電車が最も一般的。乗り換えの必要がなく簡単です。しかし、移動区間や状況によっては、バスや車、船が便利な場合もあります。', '["https://resources.matcha-jp.com/resize/720x2000/2022/04/12-125511.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/06-49568.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/06-49569.webp","https://resources.matcha-jp.com/resize/720x2000/2023/02/09-134636.webp"]'::jsonb, '2019-02-04'::timestamptz),
  ('https://matcha-jp.com/jp/4072', 'ja', 28, '大阪・京都から1時間！有馬温泉完全ガイドーオススメ日帰り温泉、カフェ、おみやげ', '有馬温泉は、1000年以上の歴史がある日本最古の温泉。黄金の温泉「金泉」や、古い街並みが続く温泉街など、魅力にあふれた温泉地です。大阪、京都からもアクセス至便。そんな有馬温泉で絶対行きたいオススメ日帰り温泉、カフェ、おみやげ店などをご紹介します！

「湯本坂」。細いけれど、これがメインストリート 有馬温泉(ありまおんせん)は、兵庫県にある日本最古と言われる温泉。1000年以上前まで遡る歴史があります。

温泉街の周囲は1キロメートル四方とコンパクトですが、その中に温泉宿やお店がぎゅっと集結。湯本坂という坂道がメインストリートとなり、その両側におみやげ店、雑貨屋などが並びます。そこから横の小道に入れば、隠れ家のようなお店も。

有馬温泉の魅力は、ここでしか入ることのできない特別な温泉。そして、曲がりくねった坂道が重なり合う温泉街。何度行っても新しい発見のある温泉地です。', '["https://resources.matcha-jp.com/resize/720x2000/2018/08/09-60159.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/09-60160.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/12-60349.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/12-60333.webp"]'::jsonb, '2018-08-29'::timestamptz),
  ('https://matcha-jp.com/jp/5059', 'ja', 29, '399段の階段を登って本堂へ、奈良県「長谷寺」の見どころ', '長谷寺では、歴史的な建物や四季折々に咲き誇る花が美しく、「花の御寺」とも呼ばれています。心が洗われるような長谷寺の境内で、日常から離れ、ゆったりとした時の流れを感じてみませんか？

奈良県桜井市にある長谷寺は、686年に僧侶・道明上人(どうみょうしょうにん)が創建したと言われています。のちに道明上人の弟子・徳道上人(とくどうしょうにん)が本堂を建立。

本尊(※1)には高さ10mを超える十一面観音菩薩(じゅういちめんかんのんぼさつ)が祀られています。', '["https://resources.matcha-jp.com/resize/720x2000/2017/10/12-38412.webp"]'::jsonb, '2017-10-23'::timestamptz),
  ('https://matcha-jp.com/jp/2600', 'ja', 29, '東京から奈良へのアクセス方法！ベストは電車？バス？新幹線？', '東大寺、法隆寺など多くの見どころがある古都・奈良。京都や大阪の近くにあり、歴史や古い建築に興味のある方に人気の観光地です。本記事では、東京から奈良へのアクセス方法を、新幹線・電車・バスほか、飛行機やレンタカーなど、金額・時間を比較し解説します。

東京方面から奈良に向かう場合の交通手段はいくつかありますが、主に電車・バス・飛行機・車を利用するのが一般的でしょう。ただし奈良には新幹線の駅が無いので、新幹線を利用する場合は京都で在来線に乗り換える必要があります。

また、飛行機の場合も東京から奈良への直行便はないため、伊丹空港もしくは関西国際空港まで行き、電車やバスに乗り換える必要があるなど少し複雑です。

本記事では、訪日観光客向けのお得な周遊パス「JAPAN RAIL PASS」と「Kintetsu Rail Pass」の情報と併せて、東京方面から奈良へのアクセス方法についてわかりやすく紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2022/03/02-123427.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1918.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/02-123428.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/02-123429.webp"]'::jsonb, '2018-05-11'::timestamptz),
  ('https://matcha-jp.com/jp/4977', 'ja', 29, '奈良の三大名園のひとつ・慈光院で抹茶と和菓子を楽しむ', '古都・奈良の世界遺産「法隆寺」から少し離れたところにある慈光院では、大和三名園のひとつともいわれる庭園を眺めながら茶の湯を楽しむことができます。日常を忘れられる、そんなひと時を奈良で過ごしてみませんか？

慈光院は、奈良県大和郡山市にある臨済宗(禅宗の一派)の寺院。かつて当地周辺を治めていた片桐貞昌(かたぎりさだまさ)が、父親の死後の冥福を祈るため、1663年に建立したという長い歴史を持っています。

また、貞昌は「石州流(せきしゅうりゅう)」という茶道の流派を始めた人物でもあります。そんな片桐貞昌が建てた慈光院は、境内全体がひとつの茶室のように作られています。', '["https://resources.matcha-jp.com/resize/720x2000/2017/09/01-34995.webp"]'::jsonb, '2017-10-10'::timestamptz),
  ('https://matcha-jp.com/jp/2033', 'ja', 30, '【廃墟】まるでラピュタの世界「友ヶ島」和歌山の無人島でジブリ旅', '『天空の城ラピュタ』はスタジオジブリが手がけた世界で人気の映画作品。和歌山県の友ヶ島の「第3砲台」はラピュタの世界観を感じられる場所として、世界中の旅行者を惹きつけています。この記事では友ヶ島の「第3砲台」の魅力や友ヶ島までの行き方を紹介します。

スタジオジブリの不朽の名作『天空の城ラピュタ』は、日本で繰り返しテレビ放送され、多くの人々に愛され続けている映画作品です。その『天空の城ラピュタ』が持つ独特の世界観を彷彿とさせる無人島が、実は和歌山県に存在します。今回ご紹介するのは、そんな「友ヶ島（ともがしま）」です。

友ヶ島は、朽ちた砲台跡やうっそうとした森が、まさにラピュタに登場する廃墟を思わせる景観を作り出しています。

また、この島は2022年に放送されたアニメ作品『サマータイムレンダ』に登場する架空の島・日都ヶ島のモデルにもなっており、作品の聖地巡りを楽しむファンも多く訪れています。', '["https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123462.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123463.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123464.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123465.webp"]'::jsonb, '2016-07-08'::timestamptz),
  ('https://matcha-jp.com/jp/22777', 'ja', 30, '高野山へのアクセス！電車・車での行き方や、大阪や名古屋の主要駅からのルートも紹介', '高野山へ初めて行く人でも迷わないアクセス方法をまとめています。電車・車での行き方をはじめ、大阪・名古屋からのアクセス方法についても触れています。高野山は、数多くの寺院が立ち並ぶ世界遺産です。

高野山は、弘法大師・空海が開いた世界屈指の宗教都市であり「天空の聖地」とも呼ばれる神秘的な場所です。

和歌山県伊都郡高野町に位置しており、1,000m級の山々に囲まれた標高約800mの山上盆地に街並みが広がっています。

本記事では、初めて行く人でも迷わずに高野山へ到着できるよう、主に電車や車を使ったアクセス方法をご紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2024/11/19-210180.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/19-210181.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/19-210182.webp"]'::jsonb, '2024-11-19'::timestamptz),
  ('https://matcha-jp.com/jp/22796', 'ja', 25, '関西の日帰りデートスポット15選｜ドライブや雨の日デートにもおすすめ', '関西には日帰りで行ける魅力的なデートスポットがたくさんあります。そこで今回は、関西の日帰りデートスポット15選をご紹介します。穴場スポットや雨の日でも楽しめるスポットも紹介するので、ぜひ大切な人と足を運んでみてください！

この記事では、デートにおすすめのロマンチックな景色が見られるスポットや、雨の日でも2人で快適に過ごせるスポットをご紹介します。

巨大なジンベエザメが水槽の中を悠々と泳ぐ姿が見られたり、他にも世界最大のサンゴ礁など、海の世界を存分に体験できます。

雨の日デートや大人の落ち着いたデートにもおすすめなので、ぜひ一度訪れてみてください！', '["https://resources.matcha-jp.com/resize/720x2000/2024/11/27-212303.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/23-231833.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/27-212305.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/27-212308.webp"]'::jsonb, '2024-11-20'::timestamptz),
  ('https://matcha-jp.com/jp/6288', 'ja', 31, '夏こそ鳥取大山へ！静寂で涼しい森とアウトドア体験が楽しめる1泊2日の避暑の旅', '日本の暑い夏に快適に観光したいなら、避暑地へ出かけるのがオススメ！ 鳥取県の大山高原では、涼しい森の中を散策して歴史豊かな神社仏閣を見学したり、自然の恵みを体感できるアウトドアアクティビティを楽しんだりできますよ。本記事では夏季にぴったりの大山高原1泊2日の旅行コースを紹介します。

7月から8月は、日本ではもっとも暑い季節です。この時期に観光するなら、自然豊かなスポットや標高の高い場所へと出かけるのがオススメです。

本記事で紹介する鳥取県の大山は、西日本の避暑地として人気のスポット。大山高原は標高が高いため、ふもとの米子市内より涼しく、また豊かな森に覆われているため、暑い夏の日でも快適に過ごせるんです。

木陰にある涼しい山道を散策したり、アウトドアアクティビティを楽しんだり、絶景スポットを巡ったりと大山高原ではさまざまな楽しみがあります。', '["https://resources.matcha-jp.com/resize/720x2000/2018/07/08-57958.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/07-57936.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/07-57927.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/08-57959.webp"]'::jsonb, '2018-08-07'::timestamptz),
  ('https://matcha-jp.com/jp/6877', 'ja', 31, '『ミシュランガイド』に掲載！鳥取で最高のレストラン6選', '大阪や京都から特急で2〜3時間程度の距離にある鳥取は、新鮮なカニや最高級の和牛といった素晴らしい食べ物の宝庫。本記事では、世界的に有名なレストランのガイドブック『ミシュランガイド』にも掲載されたレストランをご紹介します。

鳥取県は、海鮮や和牛といったおいしい食べ物の産地で、大阪、京都にも負けない"食のみやこ”でもあります。そこで本記事では、世界的に有名なレストランのガイドブック『ミシュランガイド』に掲載された鳥取のお店を6軒ご紹介。

すべての店が『ミシュランガイド京都・大阪+鳥取2019』に掲載されており、地元の食材を使った絶品料理を堪能できますよ！

鳥取県東部にある鳥取市内でおいしい寿司を食べたいなら、オススメは「笹すし」。50年の歴史を誇る、家族経営の店です。', '["https://resources.matcha-jp.com/resize/720x2000/2018/12/11-67755.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/11-67756.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/11-67758.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/11-67760.webp"]'::jsonb, '2019-01-21'::timestamptz),
  ('https://matcha-jp.com/jp/5560', 'ja', 31, '築地市場よりも大迫力！？鳥取・境漁港の食＆体験を徹底解説！', '鳥取県境港市にある境漁港は、天然マグロとベニズワイガニの水揚げ量が日本一！ 周辺には絶品の海鮮グルメの名店や、おみやげ店があります。さらに境漁港では、東京の築地市場ですら見られないシーンも目の当たりにできる見学ツアーを実施しています！

鳥取県西部にある境港市(さかいみなとし)の境漁港(さかいぎょこう)は、日本有数の漁港です。特に天然のマグロとベニズワイガニの水揚げ量は日本一。

とは言っても、「漁港で観光って、どんなもの？」とイメージがわかない人もいるかもしれません。

この境漁港周辺には、絶品の海鮮グルメが楽しめる食堂や海産物のおみやげが買える店がたくさんあり、グルメスポットとして楽しめるんです。さらに、漁港の見学ツアーでは、珍しい体験もできますよ！', '["https://resources.matcha-jp.com/resize/720x2000/2017/12/22-44670.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/22-44672.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/21-44615.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/22-44673.webp"]'::jsonb, '2018-03-20'::timestamptz),
  ('https://matcha-jp.com/jp/23025', 'ja', 32, '出雲大社の観光モデルコース(半日・日帰り・1泊2日)！絶景やご当地グルメも詳しく紹介', '島根県にある出雲大社は、縁結びの神様「大国主大神(おおくにぬしのおおかみ）」を祀る神社です。周辺には歴史を感じられる観光名所も多く、全国から多くの人が訪れます。本記事では、出雲大社を観光するときのモデルコースをスケジュール別にご紹介します。

島根県にある出雲大社は、縁結びの神として有名な「大国主大神(おおくにぬしのおおかみ)」を祀る神社です。出雲大社の観光を目的に全国から多くの人が訪れていますが、島根県には他にも魅力的なスポットが数多くあります。

そこで今回の記事では、出雲大社を観光するときのモデルコースを詳しくご紹介します。半日・日帰り・1泊2日とスケジュールに分けてご紹介するので、出雲大社を訪れる予定がある方は参考にしてみてください。

午後から出雲大社を観光する場合は、長距離移動が難しいため周辺を散策するのがおすすめです。下記では、出雲大社を半日かけて観光する際のモデルコースをご紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2024/11/29-213006.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/29-213007.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/29-213008.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/29-213009.webp"]'::jsonb, '2024-11-29'::timestamptz),
  ('https://matcha-jp.com/jp/23316', 'ja', 8, '全国の最強縁切り神社・お寺10選！日本三大縁切り稲荷も紹介', '縁切りパワーが最強と言われる、おすすめの神社やお寺を一挙ご紹介します。断ち切りたくても切れない縁をバサッと切るためには、有名どころへ行くのがベターです。日本全国の縁切りスポットを探している人は、ぜひ参考にしてみてください。

現在は、全国に広がる縁切り神社やお寺には「縁切り」を願う多くの参拝者が訪れるようになりました。今回は、有名で最強とよばれる縁切りスポットを東日本と西日本にわけてご紹介します。

豊川稲荷東京別院(とよかわいなりとうきょうべついん)は、日本三大稲荷の一つ、豊川稲荷の別院です。豊川稲荷は、織田信長(おだのぶなが)や豊臣秀吉(とよとみひでよし)らが信仰していたとしても有名な寺院です。

広い境内にはさまざまなご利益を与えてくださる神様がまつられていますが、縁切りを求める場合は「叶稲荷(かのういなり)」へ行きましょう。すべての悪縁を切り、開運招福を授けていただける因縁除けの尊天様がまつられています。', '["https://resources.matcha-jp.com/resize/720x2000/2024/12/20-216331.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216607.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/24-216849.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/21-216487.webp"]'::jsonb, '2024-12-18'::timestamptz),
  ('https://matcha-jp.com/jp/24314', 'ja', 32, '【島根】足立美術館へのアクセス方法は？主要都市から電車・飛行機・車を使った行き方を解説！', '島根県にある足立美術館の最寄り駅や、東京・名古屋・大阪・福岡という主要都市からのアクセス方法を紹介。電車・新幹線、飛行機、車による行き方をそれぞれ解説します。足立美術館は、5万坪にもおよぶ美しい日本庭園が有名で、横山大観をはじめとする美術品のコレクションも見どころです。

島根県安来市にある「足立美術館」は、主に近代から現代までの日本画が展示されている美術館です。とくに横山大観の作品が数多く展示されており、別名「大観美術館」と呼ばれているほど。

また、5万坪にもおよぶ日本庭園も見どころ。米国の日本庭園専門誌で22年間連続で「日本一」に評価されており、借景されている周囲の自然も含めた美しい景色を楽しむことができます。

この記事では、東京・名古屋・大阪・福岡という主要都市から足立美術館までのアクセス方法を紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2025/03/01-226482.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/01-226483.webp"]'::jsonb, '2025-03-01'::timestamptz),
  ('https://matcha-jp.com/jp/3825', 'ja', 33, '岡山のおみやげはここで買おう！オススメのおみやげスポット4選', '岡山県には、桃やブドウなどのブランドフルーツのほか、きびだんごなどおいしいものがたくさん。本記事では、遠方からお越しの方でも安心して購入できる賞味期限の長いおみやげと、岡山駅などからのアクセスが便利なおみやげスポット4カ所を紹介します。

中国地方に位置する岡山県には、昔ながらの美しい街並みが残る倉敷や日本三名園のひとつ「岡山後楽園」など魅力的な観光スポットがあります。

そんな岡山のおみやげとして有名なのが、日本の有名なおとぎ話『桃太郎』に登場する、こちらの写真の「きびだんご(※1)」。また、瀬戸内海に面した温暖な気候を生かしてつくられた白桃やブドウなどのブランドフルーツ、瀬戸内海でとれた新鮮な魚介類もおみやげとして人気があります。

でも、海外など遠いところから訪れる場合は、賞味期限が気になりますよね。ご安心ください。岡山には、地元のおいしい水と米を使って作られた日本酒や、地元産のフルーツをそのまま缶詰にしたフルーツ缶など、比較的賞味期限が長いおみやげもたくさんあります。また、世界20カ国以上で愛される「桃太郎デニム」や「備前焼」の器も岡山の名産品。食以外のおみやげも豊富なんです。', '["https://resources.matcha-jp.com/resize/720x2000/2017/01/17-13944.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/07-13413.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/07-13415.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/07-13412.webp"]'::jsonb, '2017-02-08'::timestamptz),
  ('https://matcha-jp.com/jp/9398', 'ja', 33, '15,000円以下で5日乗り放題！「関西広島エリアパス」で岡山・広島周遊', '海に浮かぶ厳島神社の大鳥居で知られる宮島、情緒ある町並みが人気の尾道や倉敷。そんな魅力いっぱいの広島県と岡山県を、15,000円以下で5日間周遊できるのが「関西広島エリアパス」です。ここでは同パスを使ったオススメ周遊コースをお伝えします。

歴史的な町並みが人気の尾道や倉敷、美しい厳島神社で知られる宮島……。瀬戸内海に面する広島県と岡山県には、多くの魅惑的なスポットがあります。

これらをお得に周遊できるのが、JR西日本のフリーパス「関西広島エリアパス」です。

JRのフリーパスというと、30,000円弱で7日間、JRが乗り放題になる「Japan Rail Pass」が有名ですが、「関西広島エリアパス」は関西をより集中的、かつお得に旅したい人に適しています。', '["https://resources.matcha-jp.com/resize/720x2000/2021/02/17-112497.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/18-99694.webp","https://resources.matcha-jp.com/resize/720x2000/2020/02/13-97033.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/06-98923.webp"]'::jsonb, '2020-02-07'::timestamptz),
  ('https://matcha-jp.com/jp/11842', 'ja', 33, '岡山でショッピングなら西日本最大級のショッピングモール「イオンモール岡山」へ', 'JR岡山駅前にある「イオンモール岡山」は、西日本におけるイオングループの最大級のショッピングモールです。多くの店舗が免税に対応しており、岡山ならではの商品も充実しています。おみやげ、アパレル、雑貨を購入したり、地元グルメを楽しんだりするのにぴったりのスポットです。

「イオンモール岡山」は、JR岡山駅の後楽園口から地下道で直接つながっていて、簡単に行けます。

JR岡山駅の東口から一度外に出た場合も、右に曲がればすぐにイオンモールの看板を見つけられるので、迷うことはありません

「イオンモール岡山」は、広島近辺を含む中国地方で最大級のショッピングモールで、約300店舗が入っています。', '["https://resources.matcha-jp.com/resize/720x2000/2023/05/23-138451.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136380.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136381.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/30-136383.webp"]'::jsonb, '2023-04-09'::timestamptz),
  ('https://matcha-jp.com/jp/5124', 'ja', 34, '【2026】広島の人気紅葉スポット5選！宮島や縮景園の見ごろを紹介', '広島でおすすめの紅葉名所5選を厳選しました。宮島の紅葉谷公園や縮景園のライトアップ、帝釈峡の遊覧船など、見ごろ時期や秋のイベント情報を最新情報にアップデートしてご紹介します。

嚴島神社や原爆ドームなど、歴史的な建物で有名な広島県。観光はもちろん、広島県ならではのおいしい食べ物もあり人気の観光地の1つです。

今回は、秋に行くと楽しめる広島県の人気紅葉スポットを5つ紹介します。とくに秋は、気候も涼しく観光しやすいところもポイントです！

例年広島県では、10月下旬から11月中旬にかけて紅葉が楽しめます。11月の平均気温は12~13度。最高でも20度に届かなくなるので、ジャケットやカーディガンを持っていきましょう。', '["https://resources.matcha-jp.com/resize/720x2000/2025/10/07-246201.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/29-128722.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/2615.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/12-58360.webp"]'::jsonb, '2018-07-25'::timestamptz),
  ('https://matcha-jp.com/jp/1586', 'ja', 34, '普段は入ることのできない「原爆ドーム」を、中からのぞいてみよう', '広島県広島市にある「原爆ドーム」。原子爆弾の被害と平和の大切さを伝える施設として、世界遺産にも登録されている建物です。普段見ることのできない原爆ドームの内部の姿を、Googleストリートビューを利用して覗き込んでみましょう。

みなさんは「原爆ドーム」を知っていますか？ 原爆ドームは、広島県広島市にある、世界でも珍しい現存する被爆建物です。平和の大切さを世界に訴えるシンボルとして、1996年に世界遺産として登録されました。

連日世界中から観光客の訪れる原爆ドームですが、施設保存のため観光客は外から建物を眺めるだけで、内部へ足を踏み入れることはできません。

しかし、Googleのストリートビューを使えば大丈夫。今回は、普段見ることのできない原爆ドームの内部の姿を覗き込んでみましょう。', '["https://resources.matcha-jp.com/resize/720x2000/2022/07/07-128130.webp"]'::jsonb, '2016-01-25'::timestamptz),
  ('https://matcha-jp.com/jp/11239', 'ja', 34, '広島の2大ショッピングスポット「THE OUTLETS HIROSHIMA」と「イオンモール広島府中」！その人気の秘密を探る', '広島で人気のショッピングスポット「THE OUTLETS HIROSHIMA」と「イオンモール広島府中」。ブランド品や生活用品が安く購入できるほか、エンターテインメントも充実しており、観光客にも広島在住の人にもオススメです。この2大買い物スポットの魅力を紹介します！

世界遺産の厳島神社や原爆ドームで知られる広島。この有名観光地で、特に人気のショッピングスポットが「THE OUTLETS HIROSHIMA」と「イオンモール広島府中」です。

どちらもJR広島駅からアクセスしやすく、お得に買い物ができるほか、エンターテインメントも盛りだくさんです。

本記事では、この2大ショッピングスポットに、それぞれどんな特徴があるのかを紹介します。広島に観光をする人も、広島周辺に在住の人も、本記事を読んで、広島でのショッピングを満喫してくださいね！', '["https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127864.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127865.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127866.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127867.webp"]'::jsonb, '2022-06-17'::timestamptz),
  ('https://matcha-jp.com/jp/1603', 'ja', 35, '【絶景】日本一賽銭を入れづらい神社、山口「元乃隅神社」', '山口県の元乃隅神社は、日本で一番賽銭を入れづらいことで有名です。2015年には、米国CNNにて「日本の美しい風景31選」にも選ばれて、世界が認める絶景としても注目を浴びる元乃隅神社を紹介します。

日本の神社では、賽銭(さいせん)を入れて願い事をするのが定番です。普通は小銭を専用の箱に放り込むだけでいいのですが、中には賽銭を入れるだけでひと苦労の神社があるのです。

今回は、賽銭を入れることができれば願いが叶うと言われている「元乃隅神社(もとのすみじんじゃ、旧称・元乃隅稲成神社)」を、世界も認める絶景とともに紹介します。 あわせて読みたい いまさら聞けない 神社の正しい参拝方法

神社ができたきっかけは1955年にさかのぼります。地域の漁師の夢に白いキツネが現れ、「自分を祀る神社を建てよ」とお告げを与えたことが契機になったそうです。', '["https://resources.matcha-jp.com/old_thumbnails/200x2000/874.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123262.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123263.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123264.webp"]'::jsonb, '2018-03-21'::timestamptz),
  ('https://matcha-jp.com/jp/23493', 'ja', 35, '【2025】山口・防府天満宮梅まつりが2/16～3/2開催！見どころ、イベント、アクセスも紹介', '防府天満宮は山口県防府市にある神社。京都の北野天満宮、福岡の太宰府天満宮とともに日本三大天神のひとつです。そんな防府天満宮では、梅の見頃になる時期に合わせて梅まつりが開催されます。本記事では、防府天満宮の梅まつりの見どころやアクセスなどについてお伝えします。

防府天満宮は山口県防府市にある神社。防府天満宮では、梅の見頃になる2月中旬〜3月上旬にかけて、梅まつりが開催されます。

あたり一面にかぐわしい梅の香りが漂う梅まつりには、毎年各地から数多くの人が訪れるのです。

梅まつりでは梅の花を眺めて楽しめるのはもちろん、人形感謝祭などの催し物も開催されます。楽しめるポイントが多く、春の到来を感じられる素敵なイベントです。', '["https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217861.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217863.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217864.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217866.webp"]'::jsonb, '2025-01-03'::timestamptz),
  ('https://matcha-jp.com/jp/23396', 'ja', 35, '山口観光モデルコース1泊2日！温泉とグルメを満喫＋半日・2泊3日プランも', '歴史や自然、温泉を存分に満喫できる山口県の魅力的な観光旅行。錦帯橋や秋芳洞などの名所巡りに加え、湯田温泉で心身を癒す1泊2日・2泊3日モデルコースや、幕末の雰囲気を堪能する半日コースなど、さまざまなドライブプランを紹介しています。これらのコースを活用すれば、山口県の多彩な魅力を余すところなく楽しめます。

山口県には歴史と自然を感じられる「岩国エリア」や幕末の歴史スポットを巡れる「荻エリア」、海岸景観が楽しめる「下関・宇部エリア」、高原・湖沼から雄大な自然を満喫できる「秋吉エリア」などの観光スポットがあります。これらの観光地を回るには、1泊2日以上で計画を立てるのがおすすめです。

この記事では、山口の定番名所をめぐる3つのモデルコースを紹介します。山口県の豊かな自然や美味しい食べ物を楽しんで、旅を満喫しましょう。

歴史と自然を楽しむ1泊2日の山口ドライブコース。錦帯橋や岩国城を訪れ、和牛弁天で美味しい昼食を楽しみましょう。', '["https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216574.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216575.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216576.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/23-216577.webp"]'::jsonb, '2024-12-23'::timestamptz),
  ('https://matcha-jp.com/jp/4169', 'ja', 36, '【2026開催】夏の風物詩！徳島市「阿波おどり」日程・アクセス・見どころまとめ', '阿波おどりとは、四国地方、徳島県の夏の風物詩。400年以上もの歴史を持ち、日本三大盆踊りに数えられています。徳島市阿波おどりの概要、会場へのアクセスなどを紹介します。

「阿波おどり」とは、「四国地方」、徳島県の夏の風物詩。400年以上もの歴史をもち、岐阜県の郡上踊り(ぐじょうおどり)、秋田県の西馬音内の盆踊り(にしもないのぼんおどり)とともに日本三大盆踊りに数えられています。

「踊る阿呆(あほう)に見る阿呆、同じ阿呆なら踊らな損々」というメロディに合わせて男女が踊る様子は、とても賑やか。見ていて楽しくなること請け合いです。

阿波おどりには、男性たちが法被(※1)や浴衣姿で踊る男踊りと、女性たちが頭に網笠(※2)を被り浴衣を着て踊る女踊りの2種類があります。とくに、赤やピンクの浴衣を着た女性たちの女踊りは艶やかで、祭りの目玉でもあります。', '["https://resources.matcha-jp.com/resize/720x2000/2017/03/22-21906.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/22-21909.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/22-21910.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/22-21908.webp"]'::jsonb, '2017-04-20'::timestamptz),
  ('https://matcha-jp.com/jp/23132', 'ja', 36, '徳島のおしゃれカフェ7選！夜営業・インスタ映えスポットも紹介', '豊かな自然に囲まれる徳島。そんな徳島にはおしゃれなカフェが数多くあります。この記事では、徳島のおしゃれで人気なカフェを7つご紹介します。夜まで開いている店やインスタ映えする魅力的な店まで広くご紹介するので、ぜひ参考にしてみてくださいね。

そんな徳島ですが、山だけではなく海にも近いため、山海の恵みを生かした地元食材を使った料理を提供するカフェが多くあります。

広々とした店内で、開放的なひとときを過ごせるカフェも多く、コーヒーや食事はもちろん、空間的にも高い満足度が得られます。

この記事では、徳島で人気のあるおしゃれなカフェを7つご紹介します。夜遅くまで開いている店とインスタ映えする店に分けて紹介するので、ぜひご自分にぴったりなカフェを見つけてくださいね。', '["https://resources.matcha-jp.com/resize/720x2000/2024/12/08-213997.webp"]'::jsonb, '2024-12-08'::timestamptz),
  ('https://matcha-jp.com/jp/24194', 'ja', 36, '徳島観光のモデルコース！日帰りや1泊2日で回れるコースを紹介', '四国の東端に位置する徳島県。徳島といえば渦潮ですが、それ以外にどこに行けばいいか迷う人も多いでしょう。そこで本記事では、日帰りや1泊2日で徳島観光できるモデルコースをご紹介します。各スポットの特徴もお伝えするので、参考にしてくださいね。

徳島県は四国地方の東端に位置する県。最も有名な観光スポットは渦潮ですが、それ以外はあまり知らないという人もいるのでは？

たとえば、夏の徳島では「阿波おどり」が開催され、グルメではなると金時などの豊かな作物に恵まれています。

また、県内は山地が多く、面積の内約8割を山地が占めています。雄大な自然に囲まれているのも徳島の大きな特徴ですね。', '["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225224.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225225.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225226.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225227.webp"]'::jsonb, '2025-02-20'::timestamptz),
  ('https://matcha-jp.com/jp/3946', 'ja', 37, '香川県のオススメ観光スポット26選！高松、直島、小豆島、金刀比羅宮ほか', '「現代アートの聖地」として知られる直島や人気の離島・小豆島、歴史的なパワースポット・金刀比羅宮などの見どころがある香川県。ここでは、オススメの観光スポット26選を紹介します。併せて、瀬戸内国際芸術祭といったイベントや、うどんなどのグルメもお伝えします！

瀬戸内海に面する香川県は、名物グルメ・うどんや、パワースポット・金刀比羅宮がある観光地として昔から人気でした。

さらに近年は、日本最大級の現代アートの祭典「瀬戸内国際芸術祭」が開催され、多くのアート好きが訪れる場所となっています。

香川県の観光は大きく、高松市の周辺と、それ以外の地域に分かれます。そして、それぞれの場所から行ける離島もあります。本記事では、代表的なスポットを地域別に紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2023/03/13-135895.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/13-135891.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/13-135892.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/16-138236.webp"]'::jsonb, '2018-02-22'::timestamptz),
  ('https://matcha-jp.com/jp/7696', 'ja', 37, '【香川】子どもの笑顔がいっぱい！年に2日だけ入れる津嶋神社と津島ノ宮駅とは？', '海上の小島に建てられた津嶋神社は、8月4日と5日のお祭り時のみ入れる神秘的なスポット。子どもの守り神として400年以上も地域から愛されてきました。お祭りと合わせて開設されるJR津島ノ宮駅は「日本一営業日数の短い駅」であり、鉄道ファンも必見です！

香川県の三豊(みとよ)市にある津嶋神社は、8月4日と5日のお祭り時のみ参拝できる神社。瀬戸内海の小島に浮かぶ社殿の美しさと、安産や子どもの健康、縁結びのご神徳があることから、カップルや小さな子ども連れの家族に人気のスポットです。

隣接する津島ノ宮駅も、「年に2日しか電車が止まらない駅」として鉄道ファンに人気です。本記事では、津嶋神社の由来やアクセス、筆者によるお祭りレポートをお伝えします！

1590年代のある夏、現在の津嶋神社がある浦に、女性の歌声が響き渡りました。不思議に思った村人たちは、神様の言葉を人間に伝える力を持つ巫女(みこ)を介して、ご神託を受け取りました。', '["https://resources.matcha-jp.com/resize/720x2000/2019/08/05-83017.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/29-82551.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/05-83021.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/05-83022.webp"]'::jsonb, '2019-07-22'::timestamptz),
  ('https://matcha-jp.com/jp/7360', 'ja', 37, '【香川】父母ヶ浜の5つの楽しみ方！日本最高の夕日スポットでグルメも体験も楽しもう', '香川県にある父母ヶ浜は、日本最高級の夕日が楽しめる絶景スポットです。本記事では、絶景の取り方や、地元グルメが楽しめるカフェ、おみやげ店、街歩きスポット、地元の魅力が感じられる宿など、父母ヶ浜の楽しみ方を5つ紹介します！

Picture coutesy of 三豊市 香川県西部の三豊(みとよ)市にある父母ヶ浜(ちちぶがはま)は、2016年以降、SNSを通して人気となった絶景スポット。

特に夕方、美しい景観が見られることから、日本の大手旅行誌で2018年に「行ってみたい夕日絶景ランキング」第1位に選ばれました。

この絶景の秘密は、干潮時に砂浜にできる潮だまりにあります。風が弱い日は、潮だまりの水が鏡のようになり、空を美しく映し出します。', '["https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76985.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76989.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76986.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76987.webp"]'::jsonb, '2019-04-23'::timestamptz),
  ('https://matcha-jp.com/jp/4161', 'ja', 38, '【愛媛県】「坊ちゃん湯」のある道後温泉へ行こう！', '日本三古湯のひとつである道後温泉。夏目漱石ゆかりの地としても知られているこの温泉は、白鷺の傷をも治したという伝説が残ります。そんな道後温泉の効能やアクセス法、日帰り入浴スポット、オススメ旅館など、役立つ情報をまとめました。

東京駅からJR東海道・山陽新幹線で岡山駅まで行き、そこでJR特急しおかぜに乗り換えて松山駅に出ます。松山駅で伊予鉄道の道後温泉行きにお乗りください。所要時間は約7時間30分、料金は自由席で合計19,420円です。

羽田空港から松山空港までANAとJALが毎日各6便運行しており、飛行時間は1時間30分、料金は普通運賃で38,590円です。また、成田空港からはジェットスターが1日3便運行しており、飛行時間は約1時間45分、料金は6,370円からとなっています。 松山空港から道後温泉まで、リムジンバスが約40分で結んでおり、料金は460円です。

東京駅から新宿駅経由で松山駅までドリーム松山号が、また新宿駅からオレンジライナーえひめが運行しています。いずれも深夜便で、所要時間は約12時間、料金は5,900円からご利用になれます。 松山駅から伊予鉄道に乗れば道後温泉まで25分、料金は160円です。', '["https://resources.matcha-jp.com/resize/720x2000/2017/03/13-21185.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/13-21190.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/13-21186.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/13-21187.webp"]'::jsonb, '2017-04-11'::timestamptz),
  ('https://matcha-jp.com/jp/10730', 'ja', 38, '『千と千尋の神隠し』のモデル。道後温泉本館の不思議な空気に浸る', '愛媛県松山市の道後温泉は、日本最古ともいわれる日本屈指の温泉地。何百年も変わらず人々を惹きつけている理由は、独特の雰囲気にあるのかもしれません。初めての四国旅行で道後温泉を堪能しました。

四国を代表する名湯といえば、愛媛県の道後温泉。日本神話にも登場することから、日本三古湯(※1)のひとつといわれています。

東京在住のフォトグラファーである筆者は、今回、道後温泉でもっとも有名な「道後温泉本館」を訪問しました。筆者にとっては初めての四国旅行でもあり、期待に胸がふくらみます。

※1：日本三古湯……日本で古くからの歴史がある温泉のこと。有馬温泉(兵庫県)、道後温泉(愛媛県)、白浜温泉(和歌山県)の3湯。', '["https://resources.matcha-jp.com/resize/720x2000/2022/01/12-120321.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/12-120322.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/12-120323.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/12-120324.webp"]'::jsonb, '2021-08-17'::timestamptz),
  ('https://matcha-jp.com/jp/10574', 'ja', 38, '映画の舞台になったあの駅も！四国のオススメ鉄道写真スポット3選', '瀬戸内海と太平洋に囲まれ、中央に山脈が走る四国。日本の原風景が多く残るこの島には、海、山、川を背景に絶景の鉄道写真が撮れるスポットが多数あります。今回は、JR下灘駅をはじめ、徳島県と愛媛県で鉄道写真好き必見の3スポットを紹介します！

瀬戸内海と太平洋に挟まれ、中央に四国山地が走る四国には、海、山、川が織りなす多彩な絶景があります。そんな四国には、ユニークな鉄道写真が撮れるスポットもたくさん！

本記事では、四国に住む筆者が、愛媛県、徳島県で絶景の鉄道写真が撮れる3スポットを紹介します。

今回ご紹介するのはすべてJR四国の路線です。これらの路線では、アンパンマン列車、観光列車「伊予灘ものがたり」「四国まんなか千年ものがたり」など色鮮やかなラッピング列車が走っており、目を楽しませてくれますよ！', '["https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123702.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123703.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123704.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123705.webp"]'::jsonb, '2021-06-13'::timestamptz),
  ('https://matcha-jp.com/jp/23675', 'ja', 39, '高知の観光モデルコース(1泊2日・2泊3日)！グルメと絶景を制覇しよう', '高知観光のおすすめモデルコースを、1泊2日・2泊3日の2パターン紹介した記事です。高知に行ったら訪れたい定番スポットや、絶品の地元グルメも盛り込んでいます。ぜひ本記事を参考にして、高知旅行の素敵な計画を立てましょう。

高知を観光するなら、坂本龍馬に関連したスポットや四万十川、足摺岬(あしずりみさき)などを訪れて、歴史や自然を満喫するのがおすすめです。また、鰹のたたきやみそカツラーメンなどのご当地グルメも外せません。

本記事では、高知の定番スポットやおすすめグルメを盛り込んだモデルコースを、1泊2日・2泊3日の2パターン紹介します。

▼高知観光のモデルコースでグルメ・自然・歴史を満喫しよう！ ▼【1泊2日】高知をまるっと楽しむモデルコース', '["https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220269.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220252.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220254.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220255.webp"]'::jsonb, '2025-01-17'::timestamptz),
  ('https://matcha-jp.com/jp/24053', 'ja', 39, '高知の1~12月の気温は？各季節におすすめの服装も紹介', '高知県の1月〜12月ごとの平均気温と、その時期に適した服装をまとめました。夏の暑さや冬の寒さなど、季節ごとの注意点やよくある質問についても触れていますので、旅行を計画中の方はぜひ参考にしてください。

気象庁による2024年のデータをみると、高知の年間平均気温は18.7℃とあり、冬でも比較的暖かいです。

ただし、市街地で雪が降るのは稀な半面、四国山地に囲まれた中山間地域では、冬に積雪がみられることもあります。

気象庁の2024年のデータによると、高知の最高気温は37.7℃(7月)、最低気温は-2.9℃(1月)とあります。', '["https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223927.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223928.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223929.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/12-223932.webp"]'::jsonb, '2025-02-12'::timestamptz),
  ('https://matcha-jp.com/jp/23234', 'ja', 39, '高知のおすすめグルメ5選！鍋焼きラーメン・カツオなどランキングで紹介！', '高知県に行ったらぜひ味わいたい、おすすめのグルメをランキング形式で紹介した記事です。海や川の恵みが豊かな高知県では、カツオや四万十うなぎ、クエなどの名物料理を味わえます。鍋焼きラーメンや地鶏の土佐ジローも有名なので、おすすめの店舗をしっかりチェックしておきましょう。

高知に旅行に行ったら、ご当地グルメを味わうのも旅の楽しみのひとつです。高知には海の幸をはじめとして、地元の特産品を使った名物料理が数多くあります。

高知旅行のプランを立てるのであれば、ぜひ本記事を参考にしてグルメの計画も立てておきましょう。

▼高知に行ったら絶対に食べたい名物・B級グルメをご紹介！ ▼大地の恵みや海の恵み！高知のおすすめグルメとは？ ▼1位.カツオのタタキ', '["https://resources.matcha-jp.com/resize/720x2000/2024/12/18-215773.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215243.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215244.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/18-215774.webp"]'::jsonb, '2024-12-13'::timestamptz),
  ('https://matcha-jp.com/jp/6301', 'ja', 40, '5000杯食べたマニアがオススメ！福岡県・博多周辺の激ウマ人気ラーメン8選', '通算5000杯以上のラーメンを食べた筆者が、福岡県・博多のオススメラーメンを厳選してご紹介します。この記事では、博多名物の豚骨ラーメンをはじめ、博多でも増えている豚骨以外のラーメンも紹介しています。博多のラーメン情報なら、MATCHAを見れば間違いない。

福岡県・博多と聞くと、白濁したスープの豚骨ラーメンを思い浮かべる人は多いのではないでしょうか。

もちろん、博多ではまだまだ豚骨ラーメンが多いのですが、最近ではそれ以外のラーメンも見かけるようになりました。この記事では豚骨ラーメンに加えて、博多で最近増えている豚骨以外のラーメンも紹介しています。

博多と言えば、やはり豚骨ラーメンが有名。その中でも特に人気が高いのが、この「博多一双 博多駅東本店」です。ラーメンは豚骨ラーメン1種類のみで、あとはトッピングとサイドメニューだけというシンプルなメニュー構成(写真の「ラーメン」は、税込650円)。', '["https://resources.matcha-jp.com/resize/720x2000/2018/07/09-58093.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58103.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58104.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58105.webp"]'::jsonb, '2018-07-25'::timestamptz),
  ('https://matcha-jp.com/jp/1354', 'ja', 40, '【2026】福岡の紅葉名所8選！見ごろ時期やライトアップ情報も紹介', '福岡でおすすめの紅葉スポット8選を厳選しました！舞鶴公園や友泉亭公園など博多からアクセス抜群の名所、秋月城跡や竈門神社のライトアップ、見ごろ時期や秋のグルメをご紹介します。

九州地方の北部にある福岡は、美しい自然、温かい人々、それから数々のおいしいグルメで有名です。

そんな福岡を秋に訪れたら、ぜひ紅葉を見に行ってください。今回は秋に福岡を訪れたら絶対に行きたい紅葉スポットを8ヶ所ご紹介します。

福岡の例年の見ごろは11月中旬〜12月上旬。その年の気候や場所によって、紅葉の時期は微妙に異なりますのでご注意ください。', '["https://resources.matcha-jp.com/resize/720x2000/2025/10/07-246201.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58455.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58553.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58458.webp"]'::jsonb, '2018-11-15'::timestamptz),
  ('https://matcha-jp.com/jp/2624', 'ja', 40, '福岡市・博多でオススメの観光スポット11選＆グルメ', '九州で最大の都市・福岡市(博多)は、ラーメンやもつ鍋といったグルメから、ショッピングスポット、観光スポット、エンターテインメントまで充実した人気の観光地です。本記事では、福岡市(博多)でオススメの観光スポット12選とグルメ4選を紹介します。

福岡県は九州地方で一番大きな県です。その中心都市・福岡市は、九州旅行のハブとも言える大都市です。

那珂川の西側は「福岡」、那珂川の東側は「博多」と呼ばれます。博多ラーメン、もつ鍋といった人気のご当地グルメがあるほか、ショッピングスポットもたくさんあり、「海の中道海浜公園」のように美しい景勝地もあります

さらに近年は、「マリンワールド 海の中道」や「ガンダムパーク福岡」など、エンターテインメントの施設も充実してきました。', '["https://resources.matcha-jp.com/resize/720x2000/2022/12/30-133403.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/10-122517.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/31-96152.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/28-133386.webp"]'::jsonb, '2016-12-19'::timestamptz),
  ('https://matcha-jp.com/jp/9568', 'ja', 40, '【2026】福岡のアウトレット・買い物スポット8選！セール情報もあわせて紹介', '福岡は、おいしいグルメに加え、買い物が楽しめる街です。本記事では、福岡在住の経験がある筆者が、THE OUTLETS KITAKYUSHUをはじめとするアウトレットモールのほか、デパート、ショッピングモールなどのショッピングスポットを紹介します。

九州の玄関口・福岡空港から中心部まで地下鉄で5分で行ける福岡市は、近年、人気が急上昇しています。なぜなら、おいしいグルメに加えて、ショッピングをするにも便利な街だからです！

本記事では、福岡市中心部、そして福岡県内にあるアウトレットモールやショッピングモールを厳選して紹介します。本記事を読めば、福岡での買い物もバッチリ！

福岡県、またその近隣エリアには、THE OUTLETS KITAKYUSHU、鳥栖プレミアム・アウトレットの2つのアウトレットモールと、一部アウトレット店舗が入ったマークイズ福岡ももちがあります。', '["https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127833.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127837.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99807.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99808.webp"]'::jsonb, '2020-03-23'::timestamptz),
  ('https://matcha-jp.com/jp/22375', 'ja', 40, '九州の紅葉の名所＆穴場スポット厳選10選。見ごろとライトアップ情報も', 'この記事では、九州の紅葉スポットをお探しの方に向けて、九州の紅葉の見頃時期と名所・穴場スポット10選をご紹介します。見ごろやライトアップ情報も紹介するので、ぜひ参考にしてみてください！

標高の高いエリアでは、10月中旬から10月下旬にかけて色づき始め、紅葉のピークを迎えます。一方、標高の低いエリアでは、11月中旬から12月上旬頃が見頃になります。

気温や天候によって、紅葉の見頃時期は変わるため、事前に天気情報サイトなどをチェックしておくと良いです。

11月下旬から12月上旬にかけては、黒門周辺のカエデが紅葉し、見事な紅葉の景色が広がります。', '["https://resources.matcha-jp.com/resize/720x2000/2024/10/30-206734.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/30-206736.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/30-206737.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/19-141357.webp"]'::jsonb, '2024-10-29'::timestamptz),
  ('https://matcha-jp.com/jp/21465', 'ja', 40, '九州の各エリアの天気の特徴を解説！ 季節にあった服装・イベントなども紹介', '温暖と言われる九州の気候を県ごとに紹介します。九州は南北に長いので、エリアによって気候が異なります。県ごとの気候の特徴のほか、平均気温や湿度のデータを月ごとにまとめました。このほか季節ごとのふさわしい服装や、多くの人でにぎわうイベントの情報も掲載しています。

九州への旅行が決まってから「どこに行くか」「何を食べるか」ばかりに気をとられてはいませんか。人気のスポットやグルメと同じくらい重要なのが、天気です。

南北に長く、海に囲まれ山も多い九州は、エリアによって気候が大きく異なります。本記事では、天気を県ごとに解説するほか、季節ごとにふさわしい服装や人気のイベントを紹介します。

日本の南西部に位置し、温暖と言われる九州ですが、北部には東西に、中南部では南北に山脈が走るため、エリアによって気候は異なります。', '["https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195617.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195619.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195620.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195621.webp"]'::jsonb, '2024-09-05'::timestamptz),
  ('https://matcha-jp.com/jp/4163', 'ja', 42, '【2026年】長崎くんちに熱狂！日程・演し物・アクセス完全ガイド', '長崎くんちとは、九州地方にある長崎県・諏訪神社の秋季大祭。毎年10月7日〜9日に行われ、国指定重要無形民俗文化財に指定されています。中国やオランダ、ポルトガルの影響を受けながら発展した華やかな祭りです。長崎くんちの日程、アクセス、持ち物などをまとめました。

毎年10月7日～9日に開催され、奉納踊は国の重要無形民俗文化財に指定されています。

「くんち」は、九州北部で秋祭りを表す言葉。長崎くんち、福岡の博多おくんち、佐賀の唐津くんちは「日本三大くんち」と呼ばれています。

長崎くんちの始まりは、1634年。諏訪神社の神前で、丸山町と寄合町の女性2人が謡曲（※1）「小舞」を奉納したことが起源といわれています。', '["https://resources.matcha-jp.com/resize/720x2000/2017/03/14-21257.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/14-21256.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/14-21260.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/14-21261.webp"]'::jsonb, '2017-03-14'::timestamptz),
  ('https://matcha-jp.com/jp/24165', 'ja', 42, '長崎の観光モデルコース(1泊2日＆日帰り)！おすすめスポットを制覇しよう', '長崎観光の決定版モデルコースを紹介！ 日帰り＆1泊2日で、出島やグラバー園、大浦天主堂などの定番スポットを巡り、異国情緒あふれる街並みを満喫。長崎新地中華街や長崎出島ワーフでグルメも楽しめます。伊王島の絶景スポットやカフェ巡りもおすすめです。

長崎は、日本の中でも特に異国情緒あふれる街として知られています。江戸時代に海外との窓口となった歴史を持ち、貿易や宣教師の往来を通じて育まれた独特の文化や建築が魅力です。

出島やグラバー園、大浦天主堂など、歴史的価値の高い建造物を巡る観光も人気を集めています。港や丘から見える絶景や、新鮮な海の幸を堪能できるグルメも大きな魅力。

半日で長崎を巡るなら、午前中から少しゆったりめのスケジュールを組むのがおすすめです。10：00ごろに出発すれば、主要なスポットを十分に楽しめます。', '["https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225036.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225037.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225038.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225039.webp"]'::jsonb, '2025-02-19'::timestamptz),
  ('https://matcha-jp.com/jp/23496', 'ja', 42, '【2026】長崎ランタンフェスティバル開催日程はいつ？見どころや楽しみ方を徹底解説', 'この記事では、長崎ランタンフェスティバルに行きたい人に向けて、長崎ランタンフェスティバルの見どころや楽しみ方、2026年の日程を解説します。アクセスや駐車場情報についても解説しているので、ぜひ参考にしてみてください！

2026年は2月6日から2月23日までで、約15,000個のランタンや華やかなオブジェなど、さまざまな展示を楽しめます。また、展示だけでなく、中国の歴史を感じる「皇帝パレード」や龍踊りや二胡演奏などの「ステージイベント」など、魅力盛りだくさんなイベントになっています。

この記事では、2026長崎ランタンフェスティバルの見どころや楽しみ方、アクセス、駐車場情報などを解説するので、ぜひ最後までご覧ください！

ここからは、2026長崎ランタンフェスティバルの見どころを厳選してご紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217860.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217859.webp","https://resources.matcha-jp.com/resize/720x2000/2025/11/04-248829.webp","https://resources.matcha-jp.com/resize/720x2000/2025/11/04-248830.webp"]'::jsonb, '2025-01-05'::timestamptz),
  ('https://matcha-jp.com/jp/3733', 'ja', 43, '熊本県への行き方(東京・大阪、京都から)と熊本市内の移動方法', 'クマのかわいいキャラクター「くまモン」で知られる熊本県には、日本三名城のひとつである熊本城のほか、阿蘇山や黒川温泉などの観光スポットがあります。ここでは、東京、大阪、京都、福岡などの各都市から熊本へのアクセス方法と、熊本県内の交通情報について紹介しています。

※震災の影響により、熊本城などの観光スポットで入場が規制されている箇所があります。また阿蘇エリアも一部通行止めとなっている道がありますので、お出かけの際はご注意ください。

東京から熊本へ飛行機で行く場合は、羽田空港と成田空港が利用できます。羽田空港から熊本空港への所要時間は約1時間40分で、料金は片道10,000～40,000円ほど。ソラシドエアを選べば、低料金のチケットもあります。成田空港から熊本空港への所要時間は約2時間で、料金は片道6,000～15,000円ほど。LCCのジェットスターが運航しています。

東京から熊本までは新幹線で行くこともできます。その場合は、東京駅から東海道・山陽・九州新幹線に乗り、新大阪駅または博多駅で乗り換えると1度の乗り継ぎで熊本駅までたどり着くことができます。所要時間は約6時間、料金は片道27,000円ほどです。', '["https://resources.matcha-jp.com/resize/720x2000/2022/05/16-126603.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/16-126604.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/16-126605.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/16-126606.webp"]'::jsonb, '2017-01-17'::timestamptz),
  ('https://matcha-jp.com/jp/10045', 'ja', 43, '福岡空港から行く！熊本の秘境「黒川温泉」1泊2日ドライブ旅行', '黒川温泉は熊本県阿蘇地区の山奥にあり、九州温泉の秘境と呼ばれています。本記事では福岡空港から車で黒川温泉へ向かい、オススメ旅館、必ず食べたい料理、おみやげなどを紹介。ほかにも周辺の鍋ケ滝やわいた温泉など、美しい観光地もお伝えします。

日本には多くの温泉スポットがありますが、なかでも熊本県阿蘇山の北側にある黒川温泉は、九州の秘境にある温泉とも呼ばれる場所。緑豊かで四季の風景が美しく、多くの日本人温泉客が訪れる観光地のひとつです。

今回は九州の玄関口、福岡国際空港からレンタカーで黒川温泉へ向かいます。周辺の観光地を巡る1泊2日の旅へ、一緒に出かけましょう！

今ならレンタカーが10％割引！ニッポンレンタカー 【MATCHA限定割引コード「jyd3sWbrAM」を入力すれば10％割引で車がレンタルできます。】', '["https://resources.matcha-jp.com/resize/720x2000/2020/08/12-105959.webp","https://resources.matcha-jp.com/resize/720x2000/2020/08/12-105960.webp","https://resources.matcha-jp.com/resize/720x2000/2020/08/15-106165.webp","https://resources.matcha-jp.com/resize/720x2000/2020/08/15-106164.webp"]'::jsonb, '2020-08-13'::timestamptz),
  ('https://matcha-jp.com/jp/20814', 'ja', 43, '熊本県一の繁華街！地元民が選ぶ、上通・下通周辺のおすすめ店舗10選', '九州地方の中央部にある熊本県には、あか牛や馬刺し、カラシレンコンなど、現地ならではのご当地グルメがたくさんあります。本記事では、熊本市内で熊本名物グルメが食べられる飲食店と、ショッピングが楽しめる店舗を10店舗ご紹介します。

九州地方にある熊本県は、県内1,500か所以上で地下水が湧き出ることから「水の国」、世界有数のカルデラを持つ活火山・阿蘇山があることから「火の国」という2つの異名を持っています。

自然の恵みが降り注ぐ熊本県には、ご当地グルメやショッピングが楽しめるスポットがたくさんあり、その中心地が県内随一の繁華街である「上通(かみとおり)」「下通(しもとおり)」です。

「上通」には、おしゃれなカフェやレストランが並び、ギャラリーや書店も多く、文化的な側面も楽しめます。「下通」は親しみやすい雰囲気で、活気ある飲食店やお土産店、ショッピングモールが集まっていて、地元の人や観光客でいつも賑わっています。', '["https://resources.matcha-jp.com/resize/720x2000/2024/07/31-190556.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/30-194731.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/30-194735.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/30-194729.webp"]'::jsonb, '2024-07-31'::timestamptz),
  ('https://matcha-jp.com/jp/5278', 'ja', 44, '素泊まり宿併設！別府「駅前高等温泉」は、洋館みたいな可愛い共同浴場', '日本屈指の温泉リゾート別府。数えきれないほどたくさんの見どころが、町のいたるところにあふれています。約90年前の建物で今も営業している「駅前高等温泉」は、町の共同浴場。2Fには格安で泊まれる素泊まり宿も併設されていて、別府観光の拠点にピッタリ！

別府駅東口から、駅前通りを歩くこと約5分。まるでおとぎ話の世界に迷い込んだかのような、小さな洋館が目にとまるでしょう。こちらが、今回ご紹介する「駅前高等温泉」。地域の人達が管理する町営の温泉です。

共同浴場でありながら格安の素泊まり宿が併設されている、別府でも数少ない施設。海にも山にも繁華街にもアクセス抜群な駅前の立地で、簡易宿泊所としても利用できるため別府観光の拠点にもぴったり。約90年前の建物がそのまま使われているというのも、オススメのポイントです。

駅前高等温泉入り口のドアを開けてすぐの場所に受付があります。料金は前払いで、扉の脇にある券売機でチケットを買い、受付に渡す仕組みになっています。入浴は6：00～24：00まで。', '["https://resources.matcha-jp.com/resize/720x2000/2017/11/15-41484.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/15-41485.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/04-40576.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/15-41486.webp"]'::jsonb, '2018-01-09'::timestamptz),
  ('https://matcha-jp.com/jp/5326', 'ja', 44, '屋内で体験できる砂のサウナ！別府・竹瓦温泉「砂湯」は冬こそオススメ', '別府駅近くの竹瓦温泉は、屋内に砂を用いたサウナ「砂湯」の設備を有する、日本でも数少ない施設です。建物の中にあるから、冬でも寒くないのがオススメのポイント。古びた建物内部の観察もでき、ほかの施設では得られない体験ができるでしょう。

別府のシンボルともいうべき存在の「竹瓦温泉」は、その歴史ある建物外観もさることながら、砂を用いたサウナの「砂湯」が体験できる施設としても人気です。

豪華な見た目に反し、入浴料が300円というお手頃価格なのに加え、早朝6時30分から夜22時30分まで営業しているので、観光客だけでなく地元住民からも非常に愛されている共同浴場です。

別府には竹瓦温泉のほかにも、鉄輪の「ひょうたん温泉」や、別府観光港の隣の海沿いに「別府海浜砂湯」などに同様の施設があります。竹瓦温泉の砂湯は、屋内にあるため冬場でも凍えないというのがオススメの理由。', '["https://resources.matcha-jp.com/resize/720x2000/2017/11/13-41203.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/2534.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/07-40792.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/07-40774.webp"]'::jsonb, '2017-12-21'::timestamptz),
  ('https://matcha-jp.com/jp/10212', 'ja', 44, '荘厳な石仏に絶景、グルメ！大分県南部のオススメスポット10選', '別府や湯布院などの温泉地が有名な大分県。その南部には、絶景スポットやジオパーク、歴史が息づく町並み、自然に育まれた独特の文化があります。臼杵、佐伯、津久見、豊後大野にあるオススメ10スポットのほか、グルメや宿を紹介します！

別府温泉や湯布院などがあることから「おんせん県」と呼ばれる大分県。南部へ足を伸ばせば、海と山が織りなす絶景、世界遺産、グルメも楽しめます。

本記事では、臼杵(うすき)、佐伯(さいき)、津久見(つくみ)、豊後大野(ぶんごおおの)といった大分県南部の魅力的なスポットを紹介します。

大分県南部のオススメ宿 海鮮の宿 まつ浦 里の旅リゾート ロッジきよかわ 臼杵市――タイムスリップできる町 臼杵市は、16世紀にポルトガルや中国の商人が行き来していた国際港町でした。町並みには複数の時代の名残が感じられ、どの角を曲がっても新しい発見が待っています。', '["https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108692.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110690.webp"]'::jsonb, '2020-12-06'::timestamptz),
  ('https://matcha-jp.com/jp/2031', 'ja', 45, '【絶景】海辺の洞窟に建つ神社。宮崎県「鵜戸神宮」で運試し', '日本には絶景に建つ神社がいくつもあります。今回は、その中のひとつ宮崎県の「鵜戸神社」を絶景とともに紹介。昔から縁結びや安産祈願として親しまれている神社です。有名な「運玉」投げは、何度もチャレンジしたくなります！

周囲を海に囲まれた日本には、山口県の「元乃隅稲成神社」のような、海辺に建てられた神社が珍しくありません。

今回は、宮崎県の絶景スポットに建てられた「鵜戸神宮(うどじんぐう)」をユニークな風習と共に紹介します。

鵜戸神宮は行く場合には、レンタカーで行くことをオススメします。宮崎市内から県営バスも出ていますが、行くまでに60〜70分の時間がかかることや、バスの本数が少ないために他の観光スポットに立ち寄ることが難しくなります。', '["https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121577.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121580.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121587.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121583.webp"]'::jsonb, '2016-07-07'::timestamptz),
  ('https://matcha-jp.com/jp/23349', 'ja', 45, '地鶏が楽しめる日本全国の名店8選！種類や若鶏との違いも解説', '日本でグルメを楽しむなら、濃厚な旨味が特徴の地鶏を使った料理がおすすめです。本記事では、地鶏の基礎知識と種類、地鶏料理を味わえる全国の人気店舗を紹介します。品種ごとの風味を持つ地鶏は、焼き鳥や鍋、グリルなどさまざまな料理で楽しめます。

日本の代表的なグルメは数多くあります。その中でも、最近注目を集めているのが「地鶏」です。この記事では、各土地の名産品にもなっている地鶏の種類、一般的な鶏との違い、地鶏ならではの旨味を存分に味わえるおすすめの店舗を紹介します。

なお、在来種とは、明治時代までに国内で成立または導入され定着した38種類の鶏を指します。高級食材として扱われる地鶏は、旨味とコク、弾力のある歯ごたえが特徴です。

日本3大地鶏として知られているのが、秋田県の「比内(ひない)地鶏」、愛知県の「名古屋コーチン」、鹿児島県の「薩摩地鶏」です。', '["https://resources.matcha-jp.com/resize/720x2000/2024/12/19-216252.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/19-216253.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/20-216357.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/20-216358.webp"]'::jsonb, '2024-12-19'::timestamptz),
  ('https://matcha-jp.com/jp/23727', 'ja', 45, '宮崎の1～12月の気温まとめ！各時期に適した服装も紹介', '宮崎県は”南国”と言われるほど、九州の中でも温暖な地域です。真冬の1月でも平均気温は2桁と暖かく、グルメも観光も楽しめます。宮崎に行く時の気温や服装で気をつけたいことをシーズンごとで紹介しています。

宮崎県は九州の南東部にあるため、比較的温暖な気候の地域です。空港や街中にワシントニアパームやバナナが植えられているため、南国の雰囲気も楽しめます。シーズンごとの気候や服装など気温にフォーカスしてまとめました。

宮崎県の気温を年間平均で見ると、最高気温は22.3度、最低気温は13.6度です。

最高気温が20度を上回る月が多く、1月でも最高気温が13度と暖かいのが特徴で、年間を通して温暖な日が多く見られます。', '["https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220305.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220374.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220308.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/22-220378.webp"]'::jsonb, '2025-01-22'::timestamptz),
  ('https://matcha-jp.com/jp/6634', 'ja', 46, '天然の“泥湯”を体験しよう！鹿児島・霧島の美肌温泉「さくらさくら温泉」', '肌がきれいになる「泥」がある？ 鹿児島の温泉地・霧島にある「さくらさくら温泉」には、訪れる人を魅了してやまない「泥湯」があります。なぜ肌がきれいになるのか、実際に入って体験してみました。

肌がすべすべになる「泥の湯」がある。そんな話を聞いて、鹿児島県の霧島にやってきました。

霧島は、温泉地として有名な場所。霧島の温泉地は大きく4つに分かれ、それぞれに個性を持っています。

中でも今回ご紹介する「さくらさくら温泉」は、霧島神宮(きりしまじんぐう)温泉郷というエリアにある、他にない魅力を持った温泉旅館。塗るだけで美肌になるという「泥湯」を体験できる温泉なのです！', '["https://resources.matcha-jp.com/resize/720x2000/2018/10/01-63784.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/26-63538.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/26-63539.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/26-63540.webp"]'::jsonb, '2018-10-04'::timestamptz),
  ('https://matcha-jp.com/jp/3981', 'ja', 46, '【鹿児島】甑島に行ったら絶対立ち寄りたいオススメスポット11選', '甑島は、九州地方の最南端・鹿児島県の西の沖に浮かぶ列島です。上甑島、下甑島などの島々からなり、島ごとに特徴的な観光スポットやグルメに恵まれています。本記事では、断崖に立つ「甑大明神」などの絶景スポット、キビナゴなどの海の幸や海鮮丼、黒潮の恵いっぱいの天然塩などの甑島の魅力をまとめました。

甑島は鹿児島県の薩摩川内市にある島で、大きく上甑島(かみこしきしま)、中甑島(なかこしきしま)、下甑島(しもこしきしま)の3つに分かれています。この三島での人口は約5500人です。

甑島へ行く場合は船でアクセスするのが便利。鹿児島県川内市の川内港ターミナル(高速船)と串木野新港(船)から船が出ています。 オススメは島と本土を50分で結ぶ高速船 甑島です。1日2便(4月〜9月は3便)が行き来しており、2ヶ月前までなら予約も可能。片道は大人3,380円、子ども1,700円です。

まず最初に紹介したいのは、甑大明神。見ての通り、断崖絶壁にある神社です。甑大明神には社殿はなく、岩そのものを神として祀り、拝しています。祭儀も甑岩の近くにある平岩の上で行われていました。「甑島」地名発祥の地といわれています。', '["https://resources.matcha-jp.com/resize/720x2000/2017/02/22-19383.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/03-17461.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17977.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/03-17464.webp"]'::jsonb, '2017-04-10'::timestamptz),
  ('https://matcha-jp.com/jp/24865', 'ja', 46, '鹿児島県のローカルを楽しむ！ 地元で愛される観光＆ショッピングスポット6選', '鹿児島県に多くの有名観光地がありますが、温泉地や商店街のほか、お得に買い物ができる「スポーツデポ フレスポジャングルパーク店」や「GOLF5 鹿児島与次郎店」など地元民に愛される場所も見逃せません。本記事ではそんなローカルスポットを紹介します。

鹿児島のランドマーク 桜島 Photo by PIXTA 九州の鹿児島県といえば、多くの人がまず雄大な桜島を思い浮かべるでしょう。しかし、鹿児島県の魅力はそれだけではありません。

鹿児島県には豊かな自然、独特の文化と歴史、そして多彩な郷土料理があり、国内外から訪れる多くの観光客を魅了しています。

温泉、ショッピング、アウトドアなど、楽しみ方もさまざま。今回は、地元の人たちにも人気の観光スポットを厳選して6つ紹介します。驚きと感動に満ちた旅をしてみましょう。', '["https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232922.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232888.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233503.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233504.webp"]'::jsonb, '2025-05-26'::timestamptz),
  ('https://matcha-jp.com/jp/11764', 'ja', 47, '沖縄みやげ、ポケモンセンター、日本製家電なら、空港から直行バスで行ける「イオンモール沖縄ライカム」', '沖縄最大のショッピングセンター「イオンモール沖縄ライカム」は、那覇空港だけでなく、那覇バスターミナルからも路線バスで簡単にアクセスできます。「ポケモンセンターオキナワ」ほか、約200の店舗があり、免税店も充実。なんでもそろっているので、沖縄旅行の初日や帰国日に立ち寄り、おみやげを買うのもオススメです。

「イオンモール沖縄ライカム」は、沖縄のさまざまな場所からアクセスがよいショッピングセンター。那覇空港からは、直行の高速バスのほか、沖縄本島の南部から北部までを網羅している路線バスでも向かうことができます。

直行の高速バス152番は、料金が片道1,120円で、所要時間は約1時間。さらに、「イオンモール沖縄ライカム」でお買い上げ金額が10,000円（税込）に達すると、高速バス152番で利用できる「お帰り乗車チケット」を1枚プレゼントされるキャンペーンを実施していることがあります。最新情報は公式サイトでチェックしてみてください。

空港からほど近いモノレール旭橋駅と直結している那霸バスターミナルには、「イオンモール沖縄ライカム」を経由する路線バスが多くあります。旭橋駅付近にはホテルがたくさんあり、このバスターミナルは観光客にも多く利用されています。より気軽に行きたい場合は、レンタカーや貸切タクシーを借りるのもよいでしょう。', '["https://resources.matcha-jp.com/resize/720x2000/2023/12/07-155419.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/05-155036.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155195.webp","https://resources.matcha-jp.com/resize/720x2000/2023/11/30-154380.webp"]'::jsonb, '2023-02-27'::timestamptz),
  ('https://matcha-jp.com/jp/21491', 'ja', 47, '1度は泊まりたい！宮古島ホテルのおすすめランキング10選', '宮古島にある高級リゾートホテルを紹介します。宮古島では、本土にはない綺麗な海や自然を堪能できます。せっかく非日常を体験する旅行なら、絶景を堪能できるホテルやラグジュアリーなプライベート空間を満喫できるホテルを選びましょう。

宮古島を思いきり楽しみたいなら、「海の絶景が望めて、リゾート気分を満喫できる」「市内へのアクセスが良い」などを念頭にホテルを選択するのがおすすめです。

本記事では、宮古島で1度は泊まりたいおすすめホテルをランキング形式でご紹介します。

宮古島に宿泊するなら、本土にはない綺麗な海や原生林といった自然を満喫しましょう。ここでは宮古島でしか体験できない、リゾート気分を味わえる高級ホテルを紹介します。', '["https://resources.matcha-jp.com/resize/720x2000/2024/09/06-195832.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-195833.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-195835.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-195839.webp"]'::jsonb, '2024-09-06'::timestamptz),
  ('https://matcha-jp.com/jp/22911', 'ja', 4, '日本のお土産探しならイオンモールで！日本でのショッピングやエンターテイメントが揃う場所', 'イオンモールは日本全国に164店舗あり、どの店舗も空港や駅の近くでアクセス良好です。多言語翻訳サービスやコインロッカー、免税サービス、外国人旅行客専用クーポンなどの訪日客向けサービスもあります。いまや日本の旅行でイオンモールは欠かせない存在。イオンモールで、気軽に買い物を楽しみましょう！

日本への旅行で欠かせないのがお土産ショッピングです。しかし、スケジュールの関係で、色々なお店に寄る暇がないことも。

人気のお土産や日本限定商品が買えるかどうか分からない！そんな時は最寄りのイオンモールへ行ってみましょう！

全国の多く店舗は駅や空港からアクセス良好で、旅行客にとって理想的な買い物スポットです。', '["https://resources.matcha-jp.com/resize/720x2000/2024/11/26-211988.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/16-219307.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/16-219306.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/26-211993.webp"]'::jsonb, '2024-12-14'::timestamptz),
  ('https://matcha-jp.com/jp/11344', 'ja', 41, '2022年9月23日開業！西九州新幹線と沿線スポット紹介', '2022年に日本で最も新しい新幹線「西九州新幹線」が武雄温泉駅から長崎駅までを結びます。この路線の開業に伴い、福岡-長崎間の移動時間も大幅に30分短縮！この新路線と沿線のスポットについて早速紹介します！

特急しかなかった時代に比べ、博多-長崎間の乗車時間が約30分短縮され、長崎と博多の地縁的・経済的な結びつきがさらに深まり、観光客にとっても大きなメリットとなるでしょう。

西九州新幹線は66キロの道のりです。武雄温泉駅、嬉野温泉駅、新大村駅、諫早駅、長崎駅の五つの駅があり、どの駅にも観光スポットが多くあります。

温泉自体の歴史は古く、戦国時代には負傷した兵士を治療する湯治場としても利用され、江戸時代の末期には、長崎を往き来する志士や文人が多く休憩の場として利用しました。長崎から佐世保市内へ行く時もこの駅で乗り換えます。 location_on 武雄温泉', '["https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129754.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129755.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129753.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/28-123335.webp"]'::jsonb, '2022-09-16'::timestamptz)
